from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits

import traceback

PERSON_NAME = "Sofia Coppola"
DIRECTING_DEPARTMENT_HINTS = ["directing"]
DIRECTOR_JOB_HINTS = ["director"]


def find_person_record(person_records, target_name):
    results = person_records.get("results", []) if isinstance(person_records, dict) else []
    target_lower = str(target_name).lower()

    if not results:
        return None

    for person in results:
        name = str(person.get("name", ""))
        original_name = str(person.get("original_name", ""))
        if target_lower in name.lower() or target_lower in original_name.lower():
            return person

    return results[0]


def extract_person_id(person_record):
    if not isinstance(person_record, dict):
        return None
    return person_record.get("id")


def is_directing_credit(credit):
    department = str(credit.get("department", "")).lower()
    job = str(credit.get("job", "")).lower()

    department_match = any(hint in department for hint in DIRECTING_DEPARTMENT_HINTS)
    job_match = any(hint in job for hint in DIRECTOR_JOB_HINTS)

    return department_match or job_match


def get_directed_movie_credits(person_id):
    movie_credits = Get_person_movie_credits(person_id)
    crew = movie_credits.get("crew", []) if isinstance(movie_credits, dict) else []
    directed_movies = [credit for credit in crew if is_directing_credit(credit)]
    return directed_movies


def count_items(items):
    return len(items) if items is not None else 0


def get_number_of_movies_directed_by_sofia_coppola():
    person_records = Search_person(PERSON_NAME)
    person_record = find_person_record(person_records, PERSON_NAME)
    if person_record is None:
        return 0

    person_id = extract_person_id(person_record)
    if person_id is None:
        return 0

    directed_movie_credits = get_directed_movie_credits(person_id)
    return count_items(directed_movie_credits)


def main():
    movie_count = get_number_of_movies_directed_by_sofia_coppola()
    print(movie_count)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
