from Search_movie import Search_movie
from Get_movie_credits import Get_movie_credits

import traceback

MOVIE_TITLE = "The Dark Knight"
CAST_ORDER_KEY = "order"
CAST_NAME_KEY = "name"
RESULTS_KEY = "results"
TITLE_KEY = "title"
ID_KEY = "id"
CAST_KEY = "cast"


def search_movie_by_title(title):
    try:
        return Search_movie(title)
    except Exception as exc:
        raise RuntimeError(f"Failed to search movie '{title}': {exc}") from exc


def extract_movie_id(search_result, requested_title):
    results = search_result.get(RESULTS_KEY, [])
    if not results:
        return None

    normalized_requested = requested_title.strip().lower()
    best_match = None

    for item in results:
        title = str(item.get(TITLE_KEY, "")).strip().lower()
        original_title = str(item.get("original_title", "")).strip().lower()

        if normalized_requested in title or normalized_requested in original_title:
            best_match = item
            break

    if best_match is None:
        best_match = results[0]

    movie_id = best_match.get(ID_KEY)
    return movie_id


def get_movie_credits(movie_id):
    try:
        return Get_movie_credits(movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to get credits for movie id {movie_id}: {exc}") from exc


def identify_lead_actor(credits):
    cast_list = credits.get(CAST_KEY, [])
    if not cast_list:
        return None

    sorted_cast = sorted(
        cast_list,
        key=lambda member: member.get(CAST_ORDER_KEY, 10**9)
    )
    lead_actor = sorted_cast[0].get(CAST_NAME_KEY)
    return lead_actor


def main():
    search_result = search_movie_by_title(MOVIE_TITLE)
    movie_id = extract_movie_id(search_result, MOVIE_TITLE)

    if movie_id is None:
        print(f"No movie found for: {MOVIE_TITLE}")
        return

    credits = get_movie_credits(movie_id)
    lead_actor = identify_lead_actor(credits)

    if lead_actor:
        print(f"The lead actor in '{MOVIE_TITLE}' is {lead_actor}.")
    else:
        print(f"Could not determine the lead actor for '{MOVIE_TITLE}'.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

