from Get_top_rated_movies import Get_top_rated_movies
from Get_movie_credits import Get_movie_credits

import traceback

TOP_RATED_REGION = None
DIRECTOR_JOB_KEY = "job"
DIRECTOR_JOB_MATCH = "Director"


def safe_get_top_rated_movies():
    try:
        return Get_top_rated_movies(region=TOP_RATED_REGION)
    except Exception:
        raise


def extract_first_movie(top_rated_payload):
    results = top_rated_payload.get("results", []) if isinstance(top_rated_payload, dict) else []
    if not results:
        return None
    return results[0]


def safe_get_movie_credits(movie_id):
    try:
        return Get_movie_credits(movie_id)
    except Exception:
        raise


def find_director_from_credits(credits_payload):
    crew = credits_payload.get("crew", []) if isinstance(credits_payload, dict) else []
    for member in crew:
        job_value = member.get(DIRECTOR_JOB_KEY, "")
        if isinstance(job_value, str) and DIRECTOR_JOB_MATCH.lower() in job_value.lower():
            return member.get("name")
    return None


def get_top_movie_director():
    top_rated_payload = safe_get_top_rated_movies()
    top_movie = extract_first_movie(top_rated_payload)
    if not top_movie:
        return None

    movie_id = top_movie.get("id")
    if movie_id is None:
        return None

    credits_payload = safe_get_movie_credits(movie_id)
    director_name = find_director_from_credits(credits_payload)
    return director_name


def main():
    director_name = get_top_movie_director()
    if director_name:
        print(director_name)
    else:
        print("Director not found.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

