from Search_collections import Search_collections
from Get_collection_images import Get_collection_images

import traceback

COLLECTION_NAME = "Star Wars"


def search_collection_by_name(collection_name):
    """
    Search for a collection by name and return the best matching collection id.
    """
    try:
        search_result = Search_collections(collection_name)
    except Exception as e:
        raise RuntimeError(f"Failed to search collections for '{collection_name}': {e}")

    results = search_result.get("results", [])
    if not results:
        return None

    # Prefer an exact-looking name match if available, otherwise fall back to the first result.
    normalized_target = str(collection_name).strip().lower()
    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if normalized_target in name or normalized_target in original_name:
            return item.get("id")

    return results[0].get("id")


def retrieve_collection_images(collection_id):
    """
    Retrieve image data for a collection id.
    """
    if collection_id is None:
        return {"id": None, "backdrops": [], "posters": []}

    try:
        image_result = Get_collection_images(collection_id)
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve images for collection id '{collection_id}': {e}")

    return image_result


def choose_representative_image(image_result):
    """
    Choose a representative image from collection image data.
    Prefer backdrops; if none exist, fall back to posters.
    Return the file path, or None if no images are available.
    """
    backdrops = image_result.get("backdrops", [])
    posters = image_result.get("posters", [])

    candidates = backdrops if backdrops else posters
    if not candidates:
        return None

    def sort_key(img):
        return (
            img.get("vote_average", 0) or 0,
            img.get("vote_count", 0) or 0,
            img.get("width", 0) or 0,
            img.get("height", 0) or 0,
        )

    chosen = sorted(candidates, key=sort_key, reverse=True)[0]
    return chosen.get("file_path")


def format_image_output(collection_name, collection_id, image_path):
    """
    Build a readable output string.
    """
    if image_path:
        return f"Collection: {collection_name}\nCollection ID: {collection_id}\nImage path: {image_path}"
    return f"Collection: {collection_name}\nCollection ID: {collection_id}\nImage: No image available"


def main():
    collection_id = search_collection_by_name(COLLECTION_NAME)
    image_result = retrieve_collection_images(collection_id)
    image_path = choose_representative_image(image_result)
    output = format_image_output(COLLECTION_NAME, collection_id, image_path)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

