from Search_company import Search_company
from Get_company_details import Get_company_details
from Get_company_images import Get_company_images

import traceback



SEARCH_QUERY = "Walt Disney"
SEARCH_NAME_HINT = "Disney"
FALLBACK_IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original"


def normalize_api_string(value):
    return str(value).strip().lower().replace("®", "").replace("™", "").replace("©", "")


def search_walt_disney_company():
    try:
        return Search_company(SEARCH_QUERY)
    except Exception as e:
        raise Exception(f"Search_company failed: {e}")


def get_company_id_from_search(company_record):
    results = company_record.get("results", []) if isinstance(company_record, dict) else []
    if not results:
        return None

    hint = normalize_api_string(SEARCH_NAME_HINT)
    for item in results:
        name = normalize_api_string(item.get("name", ""))
        if hint in name:
            return item.get("id")

    first_item = results[0]
    return first_item.get("id")


def get_walt_disney_company_details(company_id):
    if company_id is None:
        return {}
    return Get_company_details(company_id)


def get_walt_disney_company_images(company_id):
    if company_id is None:
        return {"id": None, "logos": []}
    return Get_company_images(company_id)


def select_logo_from_details(company_details):
    if not isinstance(company_details, dict):
        return None

    logo_path = company_details.get("logo_path")
    if logo_path:
        return {
            "source": "details",
            "logo_path": logo_path,
            "full_logo_url": f"{FALLBACK_IMAGE_BASE_URL}{logo_path}",
            "name": company_details.get("name"),
        }

    return None


def select_logo_from_images(image_assets):
    if not isinstance(image_assets, dict):
        return None

    logos = image_assets.get("logos", [])
    if not logos:
        return None

    best_logo = None
    best_score = None

    for logo in logos:
        vote_average = logo.get("vote_average", 0) or 0
        vote_count = logo.get("vote_count", 0) or 0
        score = (vote_average, vote_count)

        if best_score is None or score > best_score:
            best_score = score
            best_logo = logo

    if not best_logo:
        return None

    file_path = best_logo.get("file_path")
    return {
        "source": "images",
        "file_path": file_path,
        "full_logo_url": f"{FALLBACK_IMAGE_BASE_URL}{file_path}" if file_path else None,
        "aspect_ratio": best_logo.get("aspect_ratio"),
        "width": best_logo.get("width"),
        "height": best_logo.get("height"),
        "vote_average": best_logo.get("vote_average"),
        "vote_count": best_logo.get("vote_count"),
        "file_type": best_logo.get("file_type"),
    }


def format_output(company_record, company_details, image_assets, logo_from_details, logo_from_images):
    company_name = None
    company_id = None

    if isinstance(company_record, dict):
        results = company_record.get("results", [])
        if results:
            first = results[0]
            company_name = first.get("name")
            company_id = first.get("id")

    if isinstance(company_details, dict):
        company_name = company_details.get("name", company_name)
        company_id = company_details.get("id", company_id)

    lines = []
    lines.append("Walt Disney company lookup result")
    lines.append("--------------------------------")
    lines.append(f"Company name: {company_name if company_name is not None else 'N/A'}")
    lines.append(f"Company ID: {company_id if company_id is not None else 'N/A'}")

    if logo_from_details:
        lines.append("")
        lines.append("Logo from company details:")
        lines.append(f"  Logo path: {logo_from_details.get('logo_path', 'N/A')}")
        lines.append(f"  Full logo URL: {logo_from_details.get('full_logo_url', 'N/A')}")

    if logo_from_images:
        lines.append("")
        lines.append("Best logo from company images:")
        lines.append(f"  File path: {logo_from_images.get('file_path', 'N/A')}")
        lines.append(f"  Full logo URL: {logo_from_images.get('full_logo_url', 'N/A')}")
        lines.append(f"  File type: {logo_from_images.get('file_type', 'N/A')}")
        lines.append(f"  Vote average: {logo_from_images.get('vote_average', 'N/A')}")
        lines.append(f"  Vote count: {logo_from_images.get('vote_count', 'N/A')}")

    if not logo_from_details and not logo_from_images:
        lines.append("")
        lines.append("No logo information was available from the retrieved sources.")

    return "\n".join(lines)


def main():
    SEARCH_QUERY_CONST = "Walt Disney"
    SEARCH_NAME_HINT_CONST = "Disney"
    global SEARCH_QUERY, SEARCH_NAME_HINT
    SEARCH_QUERY = SEARCH_QUERY_CONST
    SEARCH_NAME_HINT = SEARCH_NAME_HINT_CONST

    company_record = search_walt_disney_company()
    company_id = get_company_id_from_search(company_record)
    company_details = get_walt_disney_company_details(company_id)
    image_assets = get_walt_disney_company_images(company_id)

    logo_information_from_details = select_logo_from_details(company_details)
    logo_information_from_images = select_logo_from_images(image_assets)

    output = format_output(
        company_record,
        company_details,
        image_assets,
        logo_information_from_details,
        logo_information_from_images,
    )
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
