from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_details import Get_movie_details

import traceback

PERSON_NAME = "Christopher Nolan"
DIRECTOR_JOB_KEYWORD = "director"


def find_person_by_name(person_name):
    if not person_name:
        raise ValueError("person_name is required.")
    try:
        search_result = Search_person(person_name)
    except Exception:
        raise

    results = search_result.get("results", [])
    if not results:
        return None

    normalized_target = person_name.strip().lower()
    exact_matches = []
    partial_matches = []

    for person in results:
        name = str(person.get("name", "")).strip()
        original_name = str(person.get("original_name", "")).strip()
        combined = f"{name} {original_name}".lower()
        if normalized_target in name.lower() or normalized_target in original_name.lower() or normalized_target in combined:
            exact_matches.append(person)
        else:
            partial_matches.append(person)

    candidates = exact_matches if exact_matches else results
    candidates = sorted(
        candidates,
        key=lambda p: float(p.get("popularity", 0) or 0),
        reverse=True,
    )
    return candidates[0] if candidates else None


def get_person_directing_credits(person_identifier):
    if person_identifier is None:
        return []
    person_id = person_identifier.get("id")
    if person_id is None:
        return []

    credits = Get_person_movie_credits(person_id)
    crew = credits.get("crew", [])
    directed = []
    for item in crew:
        job = str(item.get("job", "")).lower()
        department = str(item.get("department", "")).lower()
        if DIRECTOR_JOB_KEYWORD in job or DIRECTOR_JOB_KEYWORD in department:
            directed.append(item)
    return directed


def parse_release_date(movie_item):
    release_date = str(movie_item.get("release_date", "") or "")
    if len(release_date) >= 10:
        return release_date[:10]
    return release_date


def choose_most_recent_by_release_date(directed_movie_candidates):
    if not directed_movie_candidates:
        return None

    def sort_key(item):
        date_str = parse_release_date(item)
        popularity = float(item.get("popularity", 0) or 0)
        vote_average = float(item.get("vote_average", 0) or 0)
        vote_count = int(item.get("vote_count", 0) or 0)
        return (date_str, popularity, vote_average, vote_count)

    candidates = sorted(directed_movie_candidates, key=sort_key, reverse=True)
    return candidates[0] if candidates else None


def confirm_movie_details(movie_identifier):
    if movie_identifier is None:
        return None, None
    movie_id = movie_identifier.get("id")
    if movie_id is None:
        return None, None
    movie_details = Get_movie_details(movie_id)
    release_information = movie_details.get("release_date")
    return movie_details, release_information


def verify_most_recent_directed_movie(movie_details, release_information, directed_movie_candidates):
    if not movie_details:
        return None

    movie_title = movie_details.get("title")
    movie_id = movie_details.get("id")
    if movie_title is None:
        return None

    matched_candidate = None
    for candidate in directed_movie_candidates or []:
        candidate_id = candidate.get("id")
        if candidate_id == movie_id:
            matched_candidate = candidate
            break

    return {
        "title": movie_title,
        "release_date": release_information,
        "movie_id": movie_id,
        "vote_average": movie_details.get("vote_average"),
        "matched_in_credits": matched_candidate is not None,
    }


def determine_latest_directed_movie():
    person_identifier = find_person_by_name(PERSON_NAME)
    if person_identifier is None:
        return {"error": f"Could not find person: {PERSON_NAME}"}

    directed_movie_candidates = get_person_directing_credits(person_identifier)
    if not directed_movie_candidates:
        return {"error": f"No directing credits found for {PERSON_NAME}"}

    candidate_movie = choose_most_recent_by_release_date(directed_movie_candidates)
    if candidate_movie is None:
        return {"error": f"Could not determine latest directed movie for {PERSON_NAME}"}

    movie_details, release_information = confirm_movie_details(candidate_movie)
    latest_movie = verify_most_recent_directed_movie(
        movie_details,
        release_information,
        directed_movie_candidates,
    )
    if latest_movie is None:
        return {"error": "Could not verify latest movie details."}

    return latest_movie


def main():
    result = determine_latest_directed_movie()
    if isinstance(result, dict) and "error" in result:
        print(result["error"])
    else:
        title = result.get("title", "Unknown")
        release_date = result.get("release_date", "Unknown")
        movie_id = result.get("movie_id", "Unknown")
        print(f"Latest movie directed by {PERSON_NAME}: {title}")
        print(f"Release date: {release_date}")
        print(f"TMDB movie ID: {movie_id}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

