from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_top_rated_movies import Get_top_rated_movies

import traceback

MARTIN_SCORSESE_QUERY = "Martin Scorsese"
TOP_RATED_REGION = None
DIRECTOR_JOB_KEYWORDS = ("director",)


def normalize_api_text(value):
    return str(value).replace("®", "").replace("™", "").replace("©", "").strip().lower()


def choose_matching_person(person_search_results, person_name):
    results = person_search_results.get("results", []) if isinstance(person_search_results, dict) else []
    if not results:
        return None

    target = normalize_api_text(person_name)
    exact_matches = []
    partial_matches = []

    for person in results:
        name = normalize_api_text(person.get("name", ""))
        original_name = normalize_api_text(person.get("original_name", ""))
        if target == name or target == original_name:
            exact_matches.append(person)
        elif target in name or target in original_name or name in target or original_name in target:
            partial_matches.append(person)

    candidates = exact_matches or partial_matches or results
    return max(candidates, key=lambda p: float(p.get("popularity", 0) or 0))


def find_person_record(person_name):
    search_results = Search_person(person_name)
    return choose_matching_person(search_results, person_name)


def get_directed_movie_credits(person_record):
    if not person_record:
        return []

    person_id = person_record.get("id")
    if person_id is None:
        raise Exception("Martin Scorsese person record was not found.")

    credits = Get_person_movie_credits(person_id)
    crew = credits.get("crew", []) if isinstance(credits, dict) else []

    directed_movies = []
    for item in crew:
        job = normalize_api_text(item.get("job", ""))
        if any(keyword in job for keyword in DIRECTOR_JOB_KEYWORDS):
            directed_movies.append(item)
    return directed_movies


def get_top_rated_movies():
    top_rated = Get_top_rated_movies(region=TOP_RATED_REGION)
    return top_rated.get("results", []) if isinstance(top_rated, dict) else []


def build_movie_index_by_id(movies):
    index = {}
    for movie in movies or []:
        movie_id = movie.get("id")
        if movie_id is not None and movie_id not in index:
            index[movie_id] = movie
    return index


def determine_highest_rated_directed_movie(directed_movies, top_rated_movies):
    if not directed_movies:
        return None

    top_rated_index = build_movie_index_by_id(top_rated_movies)
    matched_movies = []

    for movie in directed_movies:
        movie_id = movie.get("id")
        if movie_id in top_rated_index:
            matched_movies.append(top_rated_index[movie_id])

    candidates = matched_movies or directed_movies
    return max(candidates, key=lambda m: float(m.get("vote_average", 0) or 0))


def format_movie_output(movie):
    if not movie:
        return "No directed movie data found."

    title = movie.get("title", "Unknown title")
    vote_average = movie.get("vote_average", "N/A")
    release_date = movie.get("release_date", "N/A")
    return f"Highest rated movie directed by Martin Scorsese: {title} (rating: {vote_average}, release date: {release_date})"


def main():
    martin_scorsese_record = find_person_record(MARTIN_SCORSESE_QUERY)

    if martin_scorsese_record is None:
        raise Exception("Failed to locate Martin Scorsese in the API results.")

    directed_movies = get_directed_movie_credits(martin_scorsese_record)
    top_rated_movies = get_top_rated_movies()
    highest_rated_movie = determine_highest_rated_directed_movie(directed_movies, top_rated_movies)
    print(format_movie_output(highest_rated_movie))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

