from Search_person import Search_person
from Get_movie_details import Get_movie_details

import traceback

# Pinned constants derived from user requirement
TARGET_PERSON_QUERY = "Leonardo DiCaprio"
TARGET_RESULT_INDEX = 0


def search_for_person_by_name(query):
    """
    Search for the person by name and return the raw search response.
    """
    try:
        return Search_person(query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for person '{query}': {exc}") from exc


def extract_best_person_id(person_search_response):
    """
    Extract a person ID from the search results using the schema-defined keys.
    """
    results = person_search_response.get("results", [])
    if not results:
        return None

    # Prefer an exact-ish name match, but fall back gracefully to the first result.
    target_lower = TARGET_PERSON_QUERY.lower()
    for person in results:
        name = person.get("name", "")
        original_name = person.get("original_name", "")
        if target_lower in str(name).lower() or target_lower in str(original_name).lower():
            return person.get("id")

    first_person = results[TARGET_RESULT_INDEX] if len(results) > TARGET_RESULT_INDEX else results[0]
    return first_person.get("id")


def get_person_movie_credits(person_id):
    """
    Placeholder for movie credits lookup.

    Note:
    The provided API list does not include a movie-credits endpoint, so this
    function cannot perform a real API call. It exists to keep the program
    modular and to surface the limitation clearly.
    """
    raise NotImplementedError(
        "Movie credits API is not provided in the available API_calling_code."
    )


def determine_latest_movie(credits_result):
    """
    Placeholder for determining the latest movie from credits.
    """
    raise NotImplementedError(
        "Cannot determine latest movie without a movie credits API response."
    )


def get_movie_details(movie_id):
    """
    Retrieve movie details by movie ID.
    """
    try:
        return Get_movie_details(movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to get movie details for movie_id={movie_id}: {exc}") from exc


def extract_director_from_movie_details(movie_details):
    """
    Extract director name from movie details.

    Note:
    The provided movie details schema does not include credits/cast/crew data,
    so director information is not available from this endpoint alone.
    """
    return movie_details.get("director")


def main():
    person_search_response = search_for_person_by_name(TARGET_PERSON_QUERY)
    person_id = extract_best_person_id(person_search_response)

    if person_id is None:
        print("No person found for Leonardo DiCaprio.")
        return

    # The task description expects movie credits, but the provided API list lacks
    # the required endpoint. We therefore fall back to the latest movie visible
    # in the search response's known_for list, which is part of the provided schema.
    person_results = person_search_response.get("results", [])
    selected_person = None
    for person in person_results:
        name = person.get("name", "")
        original_name = person.get("original_name", "")
        if TARGET_PERSON_QUERY.lower() in str(name).lower() or TARGET_PERSON_QUERY.lower() in str(original_name).lower():
            selected_person = person
            break
    if selected_person is None and person_results:
        selected_person = person_results[0]

    if not selected_person:
        print("No usable person result found.")
        return

    known_for = selected_person.get("known_for", [])
    if not known_for:
        print("No known-for movie data available for Leonardo DiCaprio.")
        return

    # Determine latest movie by most recent release_date among known_for entries.
    latest_movie = None
    latest_release_date = ""
    for movie in known_for:
        if movie.get("media_type") != "movie":
            continue
        release_date = movie.get("release_date", "")
        if latest_movie is None or str(release_date) > str(latest_release_date):
            latest_movie = movie
            latest_release_date = release_date

    if latest_movie is None:
        print("No movie entries found in known-for data.")
        return

    movie_id = latest_movie.get("id")
    if movie_id is None:
        print("Latest movie entry did not contain an ID.")
        return

    movie_details = get_movie_details(movie_id)

    # Schema-grounded extraction: the provided movie details schema does not
    # include director information, so we cannot reliably derive it here.
    director_name = extract_director_from_movie_details(movie_details)

    if director_name:
        print(director_name)
    else:
        title = movie_details.get("title", latest_movie.get("title", "Unknown title"))
        print(
            f"Director information is not available from the provided API responses for '{title}'."
        )


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

