import traceback

PERSON_NAME = "Catherine Hardwicke"
TARGET_KNOWN_FOR_DEPARTMENT = "directing"
TARGET_CREDIT_JOB = "Director"
MEDIA_TYPE_TV = "tv"


def search_person_by_name(person_name):
    if not person_name:
        raise ValueError("person_name is required")
    return Search_person(person_name)


def select_target_person(person_list, target_name):
    results = person_list.get("results", []) if isinstance(person_list, dict) else []
    if not results:
        return None

    target_name_lower = target_name.lower()
    for person in results:
        name = str(person.get("name", "")).lower()
        original_name = str(person.get("original_name", "")).lower()
        if target_name_lower in name or target_name_lower in original_name:
            return person

    return results[0]


def get_tv_credits_for_person(person_id):
    if person_id is None:
        raise ValueError("person_id is required")
    return Get_person_tv_credits(person_id)


def find_most_recent_directed_tv_show(tv_credits):
    crew = tv_credits.get("crew", []) if isinstance(tv_credits, dict) else []
    if not crew:
        return None

    directed = []
    for item in crew:
        department = str(item.get("department", "")).lower()
        job = str(item.get("job", "")).lower()
        if TARGET_KNOWN_FOR_DEPARTMENT.lower() in department or TARGET_CREDIT_JOB.lower() in job:
            directed.append(item)

    if not directed:
        return None

    def recency_key(item):
        first_air_date = item.get("first_air_date") or ""
        return first_air_date, item.get("popularity", 0), item.get("vote_average", 0)

    directed.sort(key=recency_key, reverse=True)
    return directed[0]


def get_tv_show_details(show_id):
    if show_id is None:
        raise ValueError("show_id is required")
    return Get_tv_details(show_id)


def extract_show_name(show_details):
    if not isinstance(show_details, dict):
        return None
    return show_details.get("name") or show_details.get("original_name")


def main():
    person_results = search_person_by_name(PERSON_NAME)
    target_person = select_target_person(person_results, PERSON_NAME)

    if not target_person:
        print(f"No person found for {PERSON_NAME}.")
        return

    person_id = target_person.get("id")
    tv_credits = get_tv_credits_for_person(person_id)
    recent_show = find_most_recent_directed_tv_show(tv_credits)

    if not recent_show:
        print(f"No recently directed TV show found for {PERSON_NAME}.")
        return

    show_id = recent_show.get("id")
    show_details = get_tv_show_details(show_id)
    show_name = extract_show_name(show_details)

    if show_name:
        print(show_name)
    else:
        print("A TV show was found, but its name is unavailable.")


