from Search_tv import Search_tv
from Get_similar_tv import Get_similar_tv

import traceback

BREAKING_BAD_QUERY = "Breaking Bad"
MAX_RECOMMENDATIONS = 5


def find_target_tv_show_id(target_title):
    if target_title is None:
        raise ValueError("target_title is required")

    search_results = Search_tv(query=target_title)
    results = search_results.get("results", [])

    if not results:
        return None, search_results

    target_lower = target_title.lower()

    def score(item):
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if name == target_lower:
            return 0
        if target_lower in name or target_lower in original_name:
            return 1
        return 2

    best_match = sorted(results, key=score)[0]
    return best_match.get("id"), search_results


def get_similar_tv_shows(tv_show_id):
    if tv_show_id is None:
        return None
    return Get_similar_tv(series_id=tv_show_id)


def format_recommendations(similar_results):
    if not similar_results:
        return []

    results = similar_results.get("results", [])
    recommendations = []
    for item in results[:MAX_RECOMMENDATIONS]:
        recommendations.append(
            {
                "name": item.get("name"),
                "first_air_date": item.get("first_air_date"),
                "vote_average": item.get("vote_average"),
                "overview": item.get("overview"),
            }
        )
    return recommendations


def print_recommendations(recommendations):
    print(f"TV shows similar to {BREAKING_BAD_QUERY}:")
    if not recommendations:
        print("No recommendations found.")
        return

    for idx, show in enumerate(recommendations, start=1):
        name = show.get("name") or "Unknown title"
        first_air_date = show.get("first_air_date") or "Unknown date"
        vote_average = show.get("vote_average")
        overview = show.get("overview") or "No overview available."
        print(f"{idx}. {name} ({first_air_date}) - Rating: {vote_average}")
        print(f"   {overview}")


def main():
    breaking_bad_id, _ = find_target_tv_show_id(BREAKING_BAD_QUERY)
    similar_shows = get_similar_tv_shows(breaking_bad_id)
    recommendations = format_recommendations(similar_shows)
    print_recommendations(recommendations)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

