from Get_trending_movies import Get_trending_movies
from Get_movie_credits import Get_movie_credits

import traceback

RESTBENCH_TOOLS_DIR = PROJECT_ROOT / "restbench tools"


TIME_WINDOW = "day"
DIRECTOR_JOB_KEY = "director"


def normalize_api_text(value):
    if not isinstance(value, str):
        return ""
    return (
        value.strip()
        .lower()
        .replace("®", "")
        .replace("™", "")
        .replace("©", "")
    )


def get_top_trending_movie():
    trending_movies = Get_trending_movies(TIME_WINDOW)
    results = trending_movies.get("results", []) if isinstance(trending_movies, dict) else []
    if not results:
        raise Exception("No trending movies found.")
    return results[0]


def get_movie_director(movie_item):
    if not isinstance(movie_item, dict):
        raise Exception("Invalid movie item.")
    movie_id = movie_item.get("id")
    if movie_id is None:
        raise Exception("Missing movie id.")

    movie_credits = Get_movie_credits(movie_id)
    crew = movie_credits.get("crew", []) if isinstance(movie_credits, dict) else []
    if not crew:
        raise Exception("No crew data found.")

    director_key = normalize_api_text(DIRECTOR_JOB_KEY)
    for member in crew:
        if not isinstance(member, dict):
            continue
        job = normalize_api_text(member.get("job", ""))
        if director_key in job or job in director_key:
            return member

    raise Exception("Director not found.")


def build_output(movie_item, director_member):
    movie_title = None
    if isinstance(movie_item, dict):
        movie_title = movie_item.get("title")

    director_name = None
    if isinstance(director_member, dict):
        director_name = director_member.get("name")

    if movie_title and director_name:
        print(f"Today's most trending movie is '{movie_title}', directed by {director_name}.")
    elif movie_title:
        print(f"Today's most trending movie is '{movie_title}', but the director could not be determined.")
    else:
        raise Exception("No trending movie data is available today.")


def main():
    movie_item = get_top_trending_movie()
    director_member = get_movie_director(movie_item)
    build_output(movie_item, director_member)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

