def search_movie_id(title):
    if not title:
        return None

    search_results = Search_movie(title)
    results = search_results.get("results", [])
    if not results:
        return None

    target = title.strip().lower()
    exact_match = None
    partial_match = None

    for item in results:
        item_title = str(item.get("title", "")).strip().lower()
        original_title = str(item.get("original_title", "")).strip().lower()

        if item_title == target or original_title == target:
            exact_match = item
            break

        if target in item_title or target in original_title:
            if partial_match is None:
                partial_match = item

    chosen = exact_match or partial_match or results[0]
    return chosen.get("id")


def get_movie_director(movie_id):
    if movie_id is None:
        return None

    credits = Get_movie_credits(movie_id)
    crew = credits.get("crew", [])

    for person in crew:
        job = str(person.get("job", "")).strip().lower()
        if job == DIRECTOR_JOB.lower():
            return person.get("name")

    return None


def main():
    movie_id = search_movie_id(MOVIE_TITLE)
    director_name = get_movie_director(movie_id)
    if director_name:
        print(director_name)
    else:
        print("Director not found")


