from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_episode_images import Get_tv_episode_images

import traceback

THE_WITCHER_QUERY = "The Witcher"
TARGET_SEASON_NUMBER = 1
TARGET_EPISODE_NUMBER = 2


def find_series_identifier(series_name):
    try:
        search_result = Search_tv(series_name)
        results = search_result.get("results", [])
        if not results:
            return None

        target_lower = series_name.lower()
        for item in results:
            name = str(item.get("name", "")).lower()
            original_name = str(item.get("original_name", "")).lower()
            if target_lower in name or target_lower in original_name:
                return item.get("id")

        first_match = results[0]
        return first_match.get("id")
    except Exception:
        raise


def get_first_season_identifier(series_id):
    try:
        series_details = Get_tv_details(series_id)
        seasons = series_details.get("seasons", [])
        if not seasons:
            return TARGET_SEASON_NUMBER

        for season in seasons:
            season_number = season.get("season_number")
            if season_number == TARGET_SEASON_NUMBER:
                return season_number

        return seasons[0].get("season_number", TARGET_SEASON_NUMBER)
    except Exception:
        raise


def get_second_episode_photo(series_id, season_number):
    try:
        episode_images = Get_tv_episode_images(series_id, season_number, TARGET_EPISODE_NUMBER)
        stills = episode_images.get("stills", [])
        if not stills:
            return None

        photo = max(stills, key=lambda x: (x.get("vote_average", 0), x.get("vote_count", 0), x.get("width", 0), x.get("height", 0)))
        return photo
    except Exception:
        raise


def format_photo_output(photo):
    if not photo:
        return "No photo available for season 1 episode 2 of The Witcher."

    file_path = photo.get("file_path", "")
    aspect_ratio = photo.get("aspect_ratio", "")
    width = photo.get("width", "")
    height = photo.get("height", "")
    vote_average = photo.get("vote_average", "")
    vote_count = photo.get("vote_count", "")
    iso_639_1 = photo.get("iso_639_1", "")

    lines = [
        "Photo found for The Witcher - Season 1, Episode 2:",
        f"file_path: {file_path}",
        f"aspect_ratio: {aspect_ratio}",
        f"width: {width}",
        f"height: {height}",
        f"iso_639_1: {iso_639_1}",
        f"vote_average: {vote_average}",
        f"vote_count: {vote_count}",
    ]
    return "\n".join(lines)


def main():
    series_id = find_series_identifier(THE_WITCHER_QUERY)
    if series_id is None:
        print("No matching TV series found for The Witcher.")
        return

    season_number = get_first_season_identifier(series_id)
    photo = get_second_episode_photo(series_id, season_number)
    print(format_photo_output(photo))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

