    """
    if not isinstance(movie, dict):
        return "No movie data available."

    title = movie.get("title")
    vote_average = movie.get("vote_average")
    vote_count = movie.get("vote_count")
    release_date = movie.get("release_date")

    parts = []
    if title is not None:
        parts.append(f"Top-1 rated movie: {title}")
    else:
        parts.append("Top-1 rated movie: <unknown title>")

    if vote_average is not None:
        parts.append(f"Rating: {vote_average}")
    if vote_count is not None:
        parts.append(f"Vote count: {vote_count}")
    if release_date is not None:
        parts.append(f"Release date: {release_date}")

    return "\n".join(parts)


