from Search_movie import Search_movie
from Get_movie_release_dates import Get_movie_release_dates

import traceback




MOVIE_TITLE = "The Matrix"
PREFERRED_COUNTRY_CODES = ("US", "GB", "CA", "AU")
PREFERRED_RELEASE_TYPE = 3
FALLBACK_RELEASE_TYPE = 1


def normalize_api_text(value):
    if not isinstance(value, str):
        return ""
    return value.replace("®", "").replace("™", "").replace("©", "").strip().lower()


def search_movie_title(movie_title):
    if movie_title is None:
        raise Exception("movie_title is required.")
    try:
        return Search_movie(movie_title)
    except Exception as e:
        raise Exception(f"Search_movie failed: {e}")


def extract_movie_id(search_result):
    results = search_result.get("results", [])
    if not results:
        return None

    target = normalize_api_text(MOVIE_TITLE)
    title_key = "title"
    for item in results:
        title = normalize_api_text(item.get(title_key, ""))
        if target in title or title in target:
            return item.get("id")

    first_item = results[0]
    return first_item.get("id")


def get_release_dates(movie_id):
    if movie_id is None:
        return None
    try:
        return Get_movie_release_dates(movie_id)
    except Exception as e:
        raise Exception(f"Get_movie_release_dates failed: {e}")


def _iter_release_entries(release_info):
    for country_entry in release_info.get("results", []):
        iso_3166_1 = country_entry.get("iso_3166_1", "")
        for release_entry in country_entry.get("release_dates", []):
            yield iso_3166_1, release_entry


def extract_theatrical_release_date(release_info):
    if not release_info:
        return None

    fallback_date = None

    for country_code in PREFERRED_COUNTRY_CODES:
        for iso_3166_1, release_entry in _iter_release_entries(release_info):
            if iso_3166_1 != country_code:
                continue
            release_type = release_entry.get("type")
            release_date = release_entry.get("release_date", "")
            if release_type == PREFERRED_RELEASE_TYPE and release_date:
                return release_date
            if fallback_date is None and release_type == FALLBACK_RELEASE_TYPE and release_date:
                fallback_date = release_date

    if fallback_date:
        return fallback_date

    for _, release_entry in _iter_release_entries(release_info):
        release_date = release_entry.get("release_date", "")
        if release_date:
            return release_date

    return None


def main():
    search_result = search_movie_title(MOVIE_TITLE)
    movie_id = extract_movie_id(search_result)
    release_info = get_release_dates(movie_id)
    release_date = extract_theatrical_release_date(release_info)
    if release_date:
        print(release_date)
    else:
        raise Exception("Release date not found")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

