from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_images import Get_movie_images

import traceback

PERSON_QUERY = "Christopher Nolan"
MIN_VOTE_COUNT = 0
MAX_MOVIES_TO_SHOW = 10
MAX_IMAGES_PER_MOVIE = 3
IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original"


def find_person_by_name(name_query):
    try:
        search_results = Search_person(name_query)
        results = search_results.get("results", [])
        if not results:
            return None

        lowered_query = (name_query or "").strip().lower()
        for person in results:
            person_name = str(person.get("name", "")).strip().lower()
            original_name = str(person.get("original_name", "")).strip().lower()
            if lowered_query and (lowered_query in person_name or lowered_query in original_name):
                return person.get("id")

        return results[0].get("id")
    except Exception:
        raise


def get_directed_movie_credits(person_id):
    movie_credits = Get_person_movie_credits(person_id)
    crew = movie_credits.get("crew", [])
    directed_movies = []
    for item in crew:
        job = str(item.get("job", "")).strip().lower()
        department = str(item.get("department", "")).strip().lower()
        if "director" in job or "director" in department:
            directed_movies.append(item)
    return directed_movies


def sort_movies_by_popularity_and_release(movies):
    def sort_key(movie):
        popularity = movie.get("popularity", 0) or 0
        release_date = movie.get("release_date", "") or ""
        vote_count = movie.get("vote_count", 0) or 0
        return (-popularity, release_date, -vote_count)

    return sorted(movies, key=sort_key)


def get_cover_images_for_movie(movie):
    movie_id = movie.get("id")
    if movie_id is None:
        return []

    movie_images = Get_movie_images(movie_id)
    selected_images = []

    backdrops = movie_images.get("backdrops", [])
    posters = movie_images.get("posters", [])

    for image in backdrops[:MAX_IMAGES_PER_MOVIE]:
        file_path = image.get("file_path")
        if file_path:
            selected_images.append({
                "type": "backdrop",
                "file_path": file_path,
                "url": f"{IMAGE_BASE_URL}{file_path}",
                "width": image.get("width"),
                "height": image.get("height"),
                "vote_average": image.get("vote_average"),
                "vote_count": image.get("vote_count"),
            })

    for image in posters[:MAX_IMAGES_PER_MOVIE]:
        file_path = image.get("file_path")
        if file_path:
            selected_images.append({
                "type": "poster",
                "file_path": file_path,
                "url": f"{IMAGE_BASE_URL}{file_path}",
                "width": image.get("width"),
                "height": image.get("height"),
                "vote_average": image.get("vote_average"),
                "vote_count": image.get("vote_count"),
            })

    return selected_images


def collect_cover_images_for_directed_movies(directed_movies):
    sorted_movies = sort_movies_by_popularity_and_release(directed_movies)
    limited_movies = sorted_movies[:MAX_MOVIES_TO_SHOW]
    all_cover_images = []

    for movie in limited_movies:
        try:
            cover_images = get_cover_images_for_movie(movie)
            all_cover_images.append({
                "movie_title": movie.get("title") or movie.get("original_title") or "Unknown Title",
                "release_date": movie.get("release_date", ""),
                "movie_id": movie.get("id"),
                "images": cover_images,
            })
        except Exception as exc:
            all_cover_images.append({
                "movie_title": movie.get("title") or movie.get("original_title") or "Unknown Title",
                "release_date": movie.get("release_date", ""),
                "movie_id": movie.get("id"),
                "images": [],
                "error": str(exc),
            })

    return all_cover_images


def format_output(cover_image_set):
    lines = []
    lines.append(f"Cover images for movies directed by {PERSON_QUERY}:")
    if not cover_image_set:
        lines.append("No directed movies or cover images were found.")
        return "\n".join(lines)

    for item in cover_image_set:
        title = item.get("movie_title", "Unknown Title")
        release_date = item.get("release_date", "")
        movie_id = item.get("movie_id", "")
        images = item.get("images", [])
        lines.append(f"\n{title} ({release_date}) [Movie ID: {movie_id}]")

        if not images:
            error = item.get("error")
            if error:
                lines.append(f"  No images available. Error: {error}")
            else:
                lines.append("  No images available.")
            continue

        for idx, image in enumerate(images, start=1):
            image_type = image.get("type", "image")
            url = image.get("url", "")
            width = image.get("width", "")
            height = image.get("height", "")
            lines.append(f"  {idx}. {image_type.title()}: {url} ({width}x{height})")

    return "\n".join(lines)


def main():
    person_id = find_person_by_name(PERSON_QUERY)
    if person_id is None:
        print(f"No person found for query: {PERSON_QUERY}")
        return

    directed_movies = get_directed_movie_credits(person_id)
    cover_image_set = collect_cover_images_for_directed_movies(directed_movies)
    output = format_output(cover_image_set)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

