from Search_movie import Search_movie
from Get_movie_keywords import Get_movie_keywords

import traceback

MOVIE_TITLE = "Titanic"
MAX_KEYWORDS_TO_DISPLAY = 10


def search_for_movie_identifier(movie_title):
    try:
        search_results = Search_movie(query=movie_title)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for movie '{movie_title}': {exc}")

    results = search_results.get("results", [])
    if not results:
        return None

    # Prefer an exact title match, but fall back to the first result if needed.
    normalized_target = movie_title.strip().lower()
    selected_movie = None

    for movie in results:
        title = str(movie.get("title", "")).strip().lower()
        original_title = str(movie.get("original_title", "")).strip().lower()
        if normalized_target in title or normalized_target in original_title:
            selected_movie = movie
            break

    if selected_movie is None:
        selected_movie = results[0]

    movie_id = selected_movie.get("id")
    return movie_id


def retrieve_movie_keywords(movie_id):
    if movie_id is None:
        return []

    try:
        keyword_results = Get_movie_keywords(movie_id=movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve keywords for movie_id={movie_id}: {exc}")

    keywords = keyword_results.get("keywords", [])
    normalized_keywords = []
    for item in keywords:
        name = item.get("name")
        if name:
            normalized_keywords.append(str(name))
    return normalized_keywords


def format_common_keywords(keywords):
    if not keywords:
        return "No keywords found for the selected movie."

    limited_keywords = keywords[:MAX_KEYWORDS_TO_DISPLAY]
    return "Common keywords associated with the movie:\n- " + "\n- ".join(limited_keywords)


def main():
    movie_id = search_for_movie_identifier(MOVIE_TITLE)
    keywords = retrieve_movie_keywords(movie_id)
    result = format_common_keywords(keywords)
    print(result)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_release_dates import Get_movie_release_dates

import traceback

CLINT_EASTWOOD_QUERY = "Clint Eastwood"
PREFERRED_COUNTRY_CODES = ["US", "GB", "CA", "AU"]
PREFERRED_RELEASE_TYPES = [3, 1, 4, 5, 6]


def safe_get(obj, key, default=None):
    if isinstance(obj, dict):
        return obj.get(key, default)
    return default


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip()


def choose_most_relevant_person(search_result):
    results = safe_get(search_result, "results", [])
    if not results:
        return None

    query = CLINT_EASTWOOD_QUERY.lower()
    best_person = None
    best_score = -1

    for person in results:
        name = normalize_text(safe_get(person, "name", "")).lower()
        original_name = normalize_text(safe_get(person, "original_name", "")).lower()
        score = 0
        if query in name:
            score += 10
        if query in original_name:
            score += 10
        score += int(float(safe_get(person, "popularity", 0)) or 0)

        if score > best_score:
            best_score = score
            best_person = person

    return best_person


def choose_latest_movie_from_credits(movie_credits):
    cast = safe_get(movie_credits, "cast", [])
    crew = safe_get(movie_credits, "crew", [])
    combined = list(cast) + list(crew)

    if not combined:
        return None

    latest_item = None
    latest_date = ""

    for item in combined:
        release_date = normalize_text(safe_get(item, "release_date", ""))
        if release_date and release_date > latest_date:
            latest_date = release_date
            latest_item = item

    if latest_item is not None:
        return latest_item

    return max(combined, key=lambda x: float(safe_get(x, "popularity", 0) or 0))


def choose_relevant_release_date(release_dates):
    results = safe_get(release_dates, "results", [])
    if not results:
        return None

    candidates = []

    for country_entry in results:
        country_code = normalize_text(safe_get(country_entry, "iso_3166_1", "")).upper()
        release_list = safe_get(country_entry, "release_dates", [])
        for release_entry in release_list:
            release_date = normalize_text(safe_get(release_entry, "release_date", ""))
            release_type = safe_get(release_entry, "type", None)
            if release_date:
                candidates.append(
                    {
                        "country_code": country_code,
                        "release_date": release_date,
                        "release_type": release_type,
                        "entry": release_entry,
                    }
                )

    if not candidates:
        return None

    preferred = []
    for code in PREFERRED_COUNTRY_CODES:
        for item in candidates:
            if code in item["country_code"]:
                preferred.append(item)

    ranked_pool = preferred if preferred else candidates

    def rank(item):
        type_rank = 99
        if item["release_type"] in PREFERRED_RELEASE_TYPES:
            type_rank = PREFERRED_RELEASE_TYPES.index(item["release_type"])
        return (item["release_date"], -type_rank)

    return max(ranked_pool, key=rank)


def search_clint_eastwood():
    return Search_person(query=CLINT_EASTWOOD_QUERY)


def get_latest_movie_from_person(person_entry):
    person_id = safe_get(person_entry, "id", None)
    if person_id is None:
        return None
    movie_credits = Get_person_movie_credits(person_id=person_id)
    return choose_latest_movie_from_credits(movie_credits)


def get_release_schedule_for_movie(movie_entry):
    movie_id = safe_get(movie_entry, "id", None)
    if movie_id is None:
        return None
    release_dates = Get_movie_release_dates(movie_id=movie_id)
    return choose_relevant_release_date(release_dates)


def format_output(person_entry, movie_entry, release_info):
    person_name = normalize_text(safe_get(person_entry, "name", CLINT_EASTWOOD_QUERY))
    movie_title = normalize_text(safe_get(movie_entry, "title", "latest movie"))
    release_date = normalize_text(safe_get(release_info, "release_date", "Unknown"))
    country_code = normalize_text(safe_get(release_info, "country_code", ""))

    if country_code:
        return f"{person_name}'s latest movie, {movie_title}, is scheduled to be released on {release_date} ({country_code})."
    return f"{person_name}'s latest movie, {movie_title}, is scheduled to be released on {release_date}."


def main():
    person_search = search_clint_eastwood()
