import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_reviews import Get_movie_reviews

import traceback

MOVIE_TITLE = "The Dark Knight"
MAX_REVIEWS_TO_PRINT = 3
MIN_CONTENT_PREVIEW_LENGTH = 300


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip()


def choose_best_matching_entry(movie_results, movie_title):
    results = movie_results.get("results", []) if isinstance(movie_results, dict) else []
    target = normalize_text(movie_title).lower()

    if not results:
        return None

    # Prefer exact-ish title matches, but keep it lenient.
    best = None
    best_score = -1

    for entry in results:
        title = normalize_text(entry.get("title", "")).lower()
        original_title = normalize_text(entry.get("original_title", "")).lower()
        overview = normalize_text(entry.get("overview", "")).lower()

        score = 0
        if target and target in title:
            score += 10
        if target and target in original_title:
            score += 8
        if "dark knight" in title:
            score += 4
        if "dark knight" in original_title:
            score += 4
        if "batman" in title or "batman" in original_title or "batman" in overview:
            score += 1

        if score > best_score:
            best_score = score
            best = entry

    return best if best is not None else results[0]


def search_movie_entry(movie_title):
    movie_results = Search_movie(query=movie_title)
    return choose_best_matching_entry(movie_results, movie_title)


def fetch_movie_reviews(movie_id):
    return Get_movie_reviews(movie_id=movie_id)


def extract_identifier(movie_entry):
    if not isinstance(movie_entry, dict):
        return None
    return movie_entry.get("id")


def transform_reviews_to_requested_summary(reviews):
    output = []

    if not isinstance(reviews, dict):
        return output

    review_items = reviews.get("results", [])
    for idx, review in enumerate(review_items[:MAX_REVIEWS_TO_PRINT], start=1):
        author = normalize_text(review.get("author", "Unknown author"))
        content = normalize_text(review.get("content", ""))
        rating = review.get("author_details", {}).get("rating", None)

        preview = content[:MIN_CONTENT_PREVIEW_LENGTH]
        if len(content) > MIN_CONTENT_PREVIEW_LENGTH:
            preview += "..."

        output.append(
            {
                "review_number": idx,
                "author": author,
                "rating": rating,
                "content_preview": preview,
            }
        )

    return output


def prepare_reviews_output(reviews):
    return transform_reviews_to_requested_summary(reviews)


def print_reviews(movie_title, movie_entry, reviews_summary):
    print(f"Movie: {movie_title}")
    if isinstance(movie_entry, dict):
        print(f"Matched Title: {movie_entry.get('title', 'Unknown')}")
        print(f"Movie ID: {movie_entry.get('id', 'Unknown')}")
        print()

    if not reviews_summary:
        print("No reviews found.")
        return

    print(f"Showing up to {len(reviews_summary)} review(s):")
    for review in reviews_summary:
        print(f"\nReview {review['review_number']}:")
        print(f"Author: {review['author']}")
        print(f"Rating: {review['rating']}")
        print(f"Content Preview: {review['content_preview']}")


def main():
    movie_entry = search_movie_entry(movie_title=MOVIE_TITLE)
    movie_id = extract_identifier(movie_entry)

    if movie_id is None:
        print(f"Movie not found: {MOVIE_TITLE}")
        return

    reviews = fetch_movie_reviews(movie_id)
    final_output = prepare_reviews_output(reviews)
    print_reviews(MOVIE_TITLE, movie_entry, final_output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

