from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_similar import Get_movie_similar

import traceback

DIRECTOR_NAME = "Francis Ford Coppola"
TARGET_MOVIE_COUNT = 5
MIN_SIMILAR_RESULTS = 5


def search_director_by_name(director_name):
    try:
        return Search_person(director_name)
    except Exception as exc:
        raise RuntimeError(f"Failed to search director '{director_name}': {exc}") from exc


def get_director_movie_credits(person_identifier):
    try:
        return Get_person_movie_credits(person_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch movie credits for person_id={person_identifier}: {exc}") from exc


def select_directed_movies(movie_credits, limit=TARGET_MOVIE_COUNT):
    crew = movie_credits.get("crew", []) if isinstance(movie_credits, dict) else []
    directed = []
    for credit in crew:
        job = str(credit.get("job", "")).strip().lower()
        department = str(credit.get("department", "")).strip().lower()
        title = credit.get("title")
        movie_id = credit.get("id")
        if "director" in job or department == "directing":
            if movie_id is not None and title:
                directed.append(credit)

    directed.sort(key=lambda x: (x.get("vote_average", 0), x.get("vote_count", 0), x.get("popularity", 0)), reverse=True)
    return directed[:limit]


def find_similar_movies(movie_identifier):
    try:
        return Get_movie_similar(movie_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch similar movies for movie_id={movie_identifier}: {exc}") from exc


def format_movie_line(movie):
    title = movie.get("title") or movie.get("original_title") or "Unknown title"
    release_date = movie.get("release_date") or "Unknown date"
    rating = movie.get("vote_average", "N/A")
    overview = movie.get("overview") or ""
    return f"- {title} ({release_date}) | Rating: {rating} | {overview}".strip()


def print_similar_movies_for_directed_movies(directed_movies):
    if not directed_movies:
        print(f"No directed movies found for {DIRECTOR_NAME}.")
        return

    print(f"Similar movies to one of the movies directed by {DIRECTOR_NAME}:\n")

    any_results = False
    for directed_movie in directed_movies:
        movie_title = directed_movie.get("title") or directed_movie.get("original_title") or "Unknown title"
        movie_id = directed_movie.get("id")
        print(f"Source movie: {movie_title}")
        if movie_id is None:
            print("  No movie ID available; skipping similar lookup.\n")
            continue

        similar_movies = find_similar_movies(movie_id)
        results = similar_movies.get("results", []) if isinstance(similar_movies, dict) else []

        if not results:
            print("  No similar movies found.\n")
            continue

        any_results = True
        for movie in results[:MIN_SIMILAR_RESULTS]:
            print(f"  {format_movie_line(movie)}")
        print()

    if not any_results:
        print("No similar movies were returned for the selected directed movies.")


def derive_director_person_id(search_results):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    def relevance_score(person):
        name = str(person.get("name", "")).lower()
        known_for_department = str(person.get("known_for_department", "")).lower()
        popularity = person.get("popularity", 0) or 0
        score = popularity
        if "director" in known_for_department:
            score += 1000
        if DIRECTOR_NAME.lower() in name:
            score += 500
        return score

    best_person = sorted(results, key=relevance_score, reverse=True)[0]
    return best_person.get("id")


def main():
    search_results = search_director_by_name(DIRECTOR_NAME)
    director_id = derive_director_person_id(search_results)

    if director_id is None:
        print(f"No person results found for '{DIRECTOR_NAME}'.")
        return

    movie_credits = get_director_movie_credits(director_id)
    directed_movies = select_directed_movies(movie_credits, TARGET_MOVIE_COUNT)
    print_similar_movies_for_directed_movies(directed_movies)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

