from Get_now_playing_movies import Get_now_playing_movies
from Get_movie_images import Get_movie_images

TMDB_REGION = "US"


def fetch_now_playing_movies():
    try:
        data = Get_now_playing_movies(region=TMDB_REGION)
        return data
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch now-playing movies: {exc}") from exc


def select_currently_showing_movie(movies_payload):
    results = movies_payload.get("results", [])
    if not results:
        return None
    return results[0]


def fetch_movie_images(movie_id):
    try:
        data = Get_movie_images(movie_id)
        return data
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch images for movie_id={movie_id}: {exc}") from exc


def select_one_image(images_payload):
    posters = images_payload.get("posters", [])
    backdrops = images_payload.get("backdrops", [])

    if posters:
        return posters[0]
    if backdrops:
        return backdrops[0]
    return None


def build_image_url(file_path):
    if not file_path:
        return None
    return f"https://image.tmdb.org/t/p/original{file_path}"


def run():
    movies_payload = fetch_now_playing_movies()
    movie = select_currently_showing_movie(movies_payload)

    if not movie:
        print("No movies are currently showing in theaters.")
        return

    movie_id = movie.get("id")
    movie_title = movie.get("title") or movie.get("original_title") or "Unknown title"

    if movie_id is None:
        print(f"Could not determine the movie ID for: {movie_title}")
        return

    images_payload = fetch_movie_images(movie_id)
    image_item = select_one_image(images_payload)

    if not image_item:
        print(f"No images were found for the currently showing movie: {movie_title}")
        return

    image_url = build_image_url(image_item.get("file_path"))
    if not image_url:
        print(f"An image record was found for {movie_title}, but it had no usable file path.")
        return

    print(f"Currently showing movie: {movie_title}")
    print(f"One image: {image_url}")


if __name__ == "__main__":
    try:
        run()
    except Exception:
        import sys
        import traceback

        traceback.print_exc(file=sys.stderr)
        raise

