import traceback

POPULAR_MOVIE_PAGE = 1


def get_most_popular_movie():
    try:
        popular_payload = Get_popular_movie()
        results = popular_payload.get("results", [])
        if not results:
            return None
        return max(results, key=lambda movie: movie.get("popularity", 0))
    except Exception:
        raise


def get_movie_keywords_for_movie(movie_id):
    try:
        if movie_id is None:
            return {"id": None, "keywords": []}
        keywords_payload = Get_movie_keywords(movie_id)
        return keywords_payload
    except Exception:
        raise


def assemble_result(movie_record, keyword_payload):
    movie_title = movie_record.get("title") if movie_record else None
    movie_id = movie_record.get("id") if movie_record else None
    keywords = keyword_payload.get("keywords", []) if keyword_payload else []

    keyword_names = []
    for keyword in keywords:
        name = keyword.get("name")
        if name:
            keyword_names.append(name)

    return {
        "movie": {
            "id": movie_id,
            "title": movie_title,
            "popularity": movie_record.get("popularity") if movie_record else None,
        },
        "keywords": keyword_names,
    }


def main():
    popular_movie = get_most_popular_movie()
    if not popular_movie:
        return {
            "movie": None,
            "keywords": [],
        }

    movie_id = popular_movie.get("id")
    movie_keywords = get_movie_keywords_for_movie(movie_id)
    return assemble_result(popular_movie, movie_keywords)


