from Get_popular_movie import Get_popular_movie
from Get_movie_keywords import Get_movie_keywords

import traceback




POPULAR_MOVIE_RESULT_LIMIT = 1


def normalize_api_text(text):
    if text is None:
        return ""
    return str(text).strip().lower().replace("®", "").replace("™", "").replace("©", "")


def get_most_popular_movie():
    try:
        return Get_popular_movie()
    except Exception as exc:
        raise Exception(f"Failed to fetch popular movies: {exc}") from exc


def extract_movie_identifier(popular_movie_result):
    results = popular_movie_result.get("results", [])
    if not isinstance(results, list) or not results:
        return None

    first_movie = results[0]
    if not isinstance(first_movie, dict):
        return None

    return first_movie.get("id")


def get_keywords_for_movie(movie_identifier):
    try:
        return Get_movie_keywords(movie_identifier)
    except Exception as exc:
        raise Exception(f"Failed to fetch keywords for movie ID {movie_identifier}: {exc}") from exc


def format_keywords_output(keywords_result):
    keywords = keywords_result.get("keywords", [])
    if not isinstance(keywords, list):
        keywords = []

    keyword_names = []
    for keyword in keywords:
        if isinstance(keyword, dict):
            name = keyword.get("name")
            if name is not None:
                keyword_names.append(name)

    return keyword_names


def print_keywords(keyword_names):
    print("Keywords of the most popular movie right now:")
    if not keyword_names:
        print("No keywords found.")
        return

    for idx, keyword in enumerate(keyword_names, start=1):
        print(f"{idx}. {keyword}")


def main():
    POPULAR_MOVIE_RESULT_LIMIT_LOCAL = POPULAR_MOVIE_RESULT_LIMIT

    popular_movie = get_most_popular_movie()
    movie_id = extract_movie_identifier(popular_movie)

    if movie_id is None:
        print("No popular movie found.")
        return

    keywords_data = get_keywords_for_movie(movie_id)
    final_keywords = format_keywords_output(keywords_data)

    if POPULAR_MOVIE_RESULT_LIMIT_LOCAL == 1:
        print_keywords(final_keywords)
    else:
        print_keywords(final_keywords[:POPULAR_MOVIE_RESULT_LIMIT_LOCAL])


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

