from Search_movie import Search_movie
from Get_movie_credits import Get_movie_credits

import traceback

TITANIC_QUERY = "Titanic"
TOP_CAST_LIMIT = 10


def search_titanic_movie():
    """
    Search for the movie Titanic and return the most relevant movie ID.
    """
    response = Search_movie(TITANIC_QUERY)

    # response_schema paths:
    # - results: list[object]
    # - results[i].id: integer
    # - results[i].title: string
    results = response.get("results", [])
    if not results:
        return None

    # Prefer the first result whose title loosely matches "Titanic"
    for item in results:
        title = str(item.get("title", "")).lower()
        original_title = str(item.get("original_title", "")).lower()
        if "titanic" in title or "titanic" in original_title:
            return item.get("id")

    return results[0].get("id")


def get_movie_credits_for_id(movie_id):
    """
    Retrieve cast and crew for a given movie ID.
    """
    if movie_id is None:
        return None
    return Get_movie_credits(movie_id)


def extract_stars(cast_and_crew_data):
    """
    Extract cast members from credits data and return readable star names.
    """
    if not cast_and_crew_data:
        return []

    # response_schema paths:
    # - cast: list[object]
    # - cast[i].name: string
    # - cast[i].character: string
    cast_list = cast_and_crew_data.get("cast", [])
    if not cast_list:
        return []

    stars = []
    for member in cast_list[:TOP_CAST_LIMIT]:
        name = member.get("name")
        character = member.get("character")
        if name:
            if character:
                stars.append(f"{name} as {character}")
            else:
                stars.append(str(name))
    return stars


def format_output(stars):
    """
    Convert extracted stars into a readable multi-line string.
    """
    if not stars:
        return "No cast information found for Titanic."

    lines = ["Stars in Titanic:"]
    for idx, star in enumerate(stars, start=1):
        lines.append(f"{idx}. {star}")
    return "\n".join(lines)


def main():
    movie_id = search_titanic_movie()
    credits = get_movie_credits_for_id(movie_id)
    stars = extract_stars(credits)
    output = format_output(stars)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

