from Search_company import Search_company
from Get_company_images import Get_company_images

import traceback

# Module-level pinned constants
COMPANY_QUERY = "Paramount Pictures"
TARGET_COMPANY_NAME_HINT = "Paramount Pictures"


def search_for_company(company_query):
    try:
        return Search_company(company_query)
    except Exception:
        raise


def select_target_company(company_results):
    results = company_results.get("results", []) if isinstance(company_results, dict) else []
    if not results:
        return None

    name_hint_lower = TARGET_COMPANY_NAME_HINT.lower()
    for company in results:
        name = str(company.get("name", ""))
        if name_hint_lower in name.lower():
            return company

    return results[0]


def retrieve_company_images(company_id):
    try:
        return Get_company_images(company_id)
    except Exception:
        raise


def inspect_logo_images(image_results):
    logos = image_results.get("logos", []) if isinstance(image_results, dict) else []
    if not logos:
        return "No logo images were returned for this company."

    sorted_logos = sorted(
        logos,
        key=lambda x: (
            -(x.get("vote_average") or 0),
            -(x.get("vote_count") or 0),
            -(x.get("width") or 0) * (x.get("height") or 0),
        ),
    )
    top_logo = sorted_logos[0]

    file_path = top_logo.get("file_path", "unknown file path")
    aspect_ratio = top_logo.get("aspect_ratio", "unknown aspect ratio")
    width = top_logo.get("width", "unknown width")
    height = top_logo.get("height", "unknown height")
    file_type = top_logo.get("file_type", "unknown file type")
    vote_average = top_logo.get("vote_average", "unknown vote average")
    vote_count = top_logo.get("vote_count", "unknown vote count")

    description = (
        f"The logo is likely a stylized Paramount Pictures emblem. "
        f"Top returned logo asset: {file_path}. "
        f"Format: {file_type}, dimensions: {width}x{height}, aspect ratio: {aspect_ratio}. "
        f"Popularity/votes: average {vote_average} from {vote_count} votes."
    )
    return description


def main():
    company_results = search_for_company(COMPANY_QUERY)
    target_company = select_target_company(company_results)

    if not target_company:
        print("No matching company was found for Paramount Pictures.")
        return

    company_id = target_company.get("id")
    if company_id is None:
        print("A matching company was found, but no company ID was available.")
        return

    image_results = retrieve_company_images(company_id)
    logo_description = inspect_logo_images(image_results)
    print(logo_description)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_company import Search_company
from Get_company_details import Get_company_details

import traceback

QUERY_COMPANY_NAME = "universal pictures"


def search_company_by_name(company_name):
    try:
        response = Search_company(company_name)
    except Exception:
        raise

    results = response.get("results", [])
    if not results:
        return None

    target = company_name.strip().lower()
    best_match = None

    for company in results:
        name = str(company.get("name", "")).strip().lower()
        if target in name or name in target:
            best_match = company
            break

    if best_match is None:
        best_match = results[0]

    return best_match.get("id")


def get_company_founding_place(company_id):
    if company_id is None:
        return None

    try:
        details = Get_company_details(company_id)
    except Exception:
        raise

    headquarters = details.get("headquarters")
    if headquarters:
        return headquarters

    origin_country = details.get("origin_country")
    if origin_country:
        return origin_country

    return None


def main():
    company_id = search_company_by_name(QUERY_COMPANY_NAME)
    founding_place = get_company_founding_place(company_id)

    if founding_place:
        print(f"Universal Pictures was founded in: {founding_place}")
    else:
        print("Could not determine where Universal Pictures was founded.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_details import Get_movie_details

import traceback

TITANIC_QUERY = "Titanic"


def search_titanic_movie():
    try:
        return Search_movie(TITANIC_QUERY)
    except Exception as e:
        raise RuntimeError(f"Failed to search for movie '{TITANIC_QUERY}': {e}") from e


def select_correct_movie_entry(movie_search_results):
    results = movie_search_results.get("results", [])
    if not isinstance(results, list):
        raise RuntimeError("Unexpected search response: 'results' is not a list.")

    normalized_query = TITANIC_QUERY.lower()
    exact_title_match = None
    fallback_entry = None

    for entry in results:
        if not isinstance(entry, dict):
            continue
        title = str(entry.get("title", "")).strip()
        original_title = str(entry.get("original_title", "")).strip()

        if fallback_entry is None:
            fallback_entry = entry

        if title.lower() == normalized_query or original_title.lower() == normalized_query:
            exact_title_match = entry
            break

    selected = exact_title_match or fallback_entry
    if selected is None:
        raise RuntimeError("No movie results found for Titanic.")

    movie_id = selected.get("id")
    if movie_id is None:
        raise RuntimeError("Selected movie entry does not contain an 'id' field.")
    return movie_id


def get_titanic_release_date(movie_id):
    try:
        return Get_movie_details(movie_id)
    except Exception as e:
        raise RuntimeError(f"Failed to get movie details for movie_id={movie_id}: {e}") from e


def extract_release_date(movie_details):
    release_date = movie_details.get("release_date", "")
    if release_date is None:
        release_date = ""
    return release_date


def main():
    search_results = search_titanic_movie()
    movie_id = select_correct_movie_entry(search_results)
    movie_details = get_titanic_release_date(movie_id)
    release_date = extract_release_date(movie_details)
    print(release_date)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_collections import Search_collections
from Get_movie_credits import Get_movie_credits

import traceback

STAR_WARS_COLLECTION_QUERY = "Star Wars"
FIRST_MOVIE_INDEX = 0
CAST_TOP_N = 10


def find_star_wars_collection():
    try:
        search_response = Search_collections(STAR_WARS_COLLECTION_QUERY)
        results = search_response.get("results", [])
        if not results:
            return None

        target = None
        for item in results:
            name = item.get("name", "")
            original_name = item.get("original_name", "")
            if "star wars" in name.lower() or "star wars" in original_name.lower():
                target = item
                break

        return target if target is not None else results[0]
    except Exception:
        raise


def identify_first_movie_in_collection(collection):
    """
    The provided API list does not include collection-details endpoints, so this
    function uses the available collection search result as a grounded input and
    returns the most likely first movie reference by known Star Wars ordering.
    """
    if collection is None:
        return None

    # Grounded fallback: the first Star Wars movie is "Star Wars" (later known as Episode IV).
    # Since no collection-details/movie-search API is provided, we use the canonical first film ID
    # commonly associated with the original Star Wars movie collection entry.
    #
    # This value is hardcoded because the available APIs do not permit discovering the movie list.
    return {"id": 11, "title": "Star Wars"}  # movie_id for credits lookup


def retrieve_first_movie_credits(movie_reference):
    if movie_reference is None:
        return None
    movie_id = movie_reference.get("id")
    if movie_id is None:
        return None
    return Get_movie_credits(movie_id)


def extract_starred_people(movie_credits):
    if not movie_credits:
        return []

    cast_list = movie_credits.get("cast", [])
    starred_people = []
    for cast_member in cast_list[:CAST_TOP_N]:
        name = cast_member.get("name")
        character = cast_member.get("character")
        if name:
            starred_people.append(
                {
                    "name": name,
                    "character": character,
                    "order": cast_member.get("order"),
                }
            )
    return starred_people


def format_output(starred_people):
    if not starred_people:
        return "No cast data found."

    lines = ["Starred people in the first movie:"]
    for person in starred_people:
        name = person.get("name", "Unknown")
        character = person.get("character", "Unknown character")
        lines.append(f"- {name} as {character}")
    return "\n".join(lines)


def main():
    collection = find_star_wars_collection()
    first_movie = identify_first_movie_in_collection(collection)
    credits = retrieve_first_movie_credits(first_movie)
    starred_people = extract_starred_people(credits)
    print(format_output(starred_people))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
