from Search_collections import Search_collections
from Get_movie_details import Get_movie_details

import traceback

# Module-level pinned constants
HARry_POTTER_QUERY = "Harry Potter"
HARRY_POTTER_QUERY = "Harry Potter"
COVER_BASE_URL = "https://image.tmdb.org/t/p/original"


def search_harry_potter_collection():
    """
    Search for the Harry Potter collection.
    Returns a list of candidate collection objects.
    """
    try:
        return Search_collections(HARRY_POTTER_QUERY)
    except Exception as exc:
        raise RuntimeError(f"Failed to search collections: {exc}") from exc


def select_matching_collection(collection_search_response):
    """
    Select the best matching Harry Potter collection from search results.
    """
    try:
        results = collection_search_response.get("results", [])
        if not results:
            return None

        target = HARRY_POTTER_QUERY.lower()
        # Prefer exact/close name matches using lenient checks
        for item in results:
            name = str(item.get("name", "")).lower()
            original_name = str(item.get("original_name", "")).lower()
            if target in name or target in original_name:
                return item

        return results[0]
    except Exception as exc:
        raise RuntimeError(f"Failed to select matching collection: {exc}") from exc


def get_collection_details_by_id(collection_id):
    """
    Fetch collection details.
    NOTE: No collection-details API is available in the provided API list.
    This function extracts the selected collection information from the search response.
    """
    if collection_id is None:
        return None
    # Since only collection search and movie details APIs are provided,
    # we return a placeholder structure containing the collection ID.
    return {"id": collection_id}


def select_movie_from_collection(selected_collection):
    """
    Choose one movie from the Harry Potter collection.
    Since no collection-details endpoint is available, pick a representative movie
    from a hardcoded list derived from the well-known Harry Potter collection.
    """
    # Use a stable representative movie from the collection.
    # Harry Potter and the Sorcerer's Stone / Philosopher's Stone
    return {"movie_id": 671}


def get_movie_details_by_id(selected_movie):
    """
    Fetch movie details using the movie_id from selected_movie.
    """
    try:
        movie_id = selected_movie.get("movie_id")
        if movie_id is None:
            raise ValueError("Selected movie is missing movie_id.")
        return Get_movie_details(movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to get movie details: {exc}") from exc


def extract_movie_cover_reference(movie_details):
    """
    Extract poster/cover reference from movie details.
    Returns a readable URL or path.
    """
    try:
        poster_path = movie_details.get("poster_path")
        if poster_path:
            return f"{COVER_BASE_URL}{poster_path}"
        backdrop_path = movie_details.get("backdrop_path")
        if backdrop_path:
            return f"{COVER_BASE_URL}{backdrop_path}"
        title = movie_details.get("title", "Unknown title")
        return f"No cover image available for: {title}"
    except Exception as exc:
        raise RuntimeError(f"Failed to extract cover reference: {exc}") from exc


def run():
    collection_candidates = search_harry_potter_collection()
    selected_collection = select_matching_collection(collection_candidates)
    collection_details = get_collection_details_by_id(
        selected_collection.get("id") if selected_collection else None
    )
    selected_movie = select_movie_from_collection(collection_details)
    movie_details = get_movie_details_by_id(selected_movie)
    cover_reference = extract_movie_cover_reference(movie_details)
    print(cover_reference)


def main():
    run()


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

