from Search_collections import Search_collections
from Get_collection_details import Get_collection_details
from Get_movie_release_dates import Get_movie_release_dates

import traceback

COLLECTION_QUERY = "The Hobbit"
RELEASE_TYPE_PRIMARY = 3  # Theatrical, used as a preferred release type when available


def find_collection_identifier(collection_name):
    """
    Search for the collection identifier using the collection name.
    Returns the best matching collection id or None if not found.
    """
    search_result = Search_collections(collection_name)
    results = search_result.get("results", [])

    if not results:
        return None

    target = collection_name.strip().lower()
    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if target in name or target in original_name or name in target or original_name in target:
            return item.get("id")

    return results[0].get("id")


def retrieve_collection_movies(collection_identifier):
    """
    Fetch collection details and return the parts list.
    """
    if collection_identifier is None:
        return []

    collection_details = Get_collection_details(collection_identifier)
    return collection_details.get("parts", [])


def extract_movie_identifier(movie):
    """
    Extract movie id from a movie object.
    """
    return movie.get("id")


def choose_release_date_from_results(release_payload):
    """
    Extract a preferred release date from the TMDB release dates payload.
    Preference:
      1) Theatrical release (type 3) in any country
      2) Any first available release date
    """
    results = release_payload.get("results", [])
    if not results:
        return None

    fallback_dates = []

    for country_entry in results:
        release_dates = country_entry.get("release_dates", [])
        for release_entry in release_dates:
            release_date = release_entry.get("release_date")
            if release_date:
                fallback_dates.append(release_date)
                release_type = release_entry.get("type")
                if release_type is not None and release_type == RELEASE_TYPE_PRIMARY:
                    return release_date

    return fallback_dates[0] if fallback_dates else None


def get_release_date_for_movie(movie_identifier):
    """
    Get release date for a single movie identifier.
    """
    if movie_identifier is None:
        return None

    release_data = Get_movie_release_dates(movie_identifier)
    return choose_release_date_from_results(release_data)


def build_release_date_list(movie_list):
    """
    Build a list of movie titles with their release dates.
    """
    release_date_list = []

    for movie in movie_list:
        movie_identifier = extract_movie_identifier(movie)
        release_date = get_release_date_for_movie(movie_identifier)
        release_date_list.append(
            {
                "movie_name": movie.get("name"),
                "original_name": movie.get("original_name"),
                "release_date": release_date,
            }
        )

    return release_date_list


def format_release_date_output(release_date_list, collection_name):
    """
    Produce readable, task-oriented output.
    """
    lines = [f"Release dates for movies in the collection '{collection_name}':"]
    if not release_date_list:
        lines.append("No movies were found in the collection.")
        return "\n".join(lines)

    for item in release_date_list:
        movie_name = item.get("movie_name") or item.get("original_name") or "Unknown title"
        release_date = item.get("release_date") or "Unknown release date"
        lines.append(f"- {movie_name}: {release_date}")

    return "\n".join(lines)


def main():
    collection_identifier = find_collection_identifier(COLLECTION_QUERY)
    movie_list = retrieve_collection_movies(collection_identifier)
    release_dates = build_release_date_list(movie_list)
    print(format_release_date_output(release_dates, COLLECTION_QUERY))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_collections import Search_collections
from Get_collection_details import Get_collection_details

import traceback

# Module-level constants pinned from user requirement / reasonable assumptions
COLLECTION_QUERY = "The Fast and the Furious"
NAME_KEY = "name"
RESULTS_KEY = "results"
PARTS_KEY = "parts"


def search_for_collection():
    try:
        response = Search_collections(COLLECTION_QUERY)
        return response
    except Exception as exc:
        raise RuntimeError(f"Failed to search collections for query '{COLLECTION_QUERY}': {exc}") from exc


def select_matched_collection(matched_collection_list):
    try:
        results = matched_collection_list.get(RESULTS_KEY, [])
        if not results:
            return None

        target = COLLECTION_QUERY.casefold()
        for collection in results:
            collection_name = str(collection.get(NAME_KEY, "")).casefold()
            if target in collection_name or collection_name in target:
                return collection.get("id")

        return results[0].get("id")
    except Exception as exc:
        raise RuntimeError(f"Failed to select matched collection: {exc}") from exc


def retrieve_collection_details(collection_identifier):
    if collection_identifier is None:
        return None
    try:
        return Get_collection_details(collection_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve collection details for id {collection_identifier}: {exc}") from exc


def extract_movies_from_collection(collection_details):
    try:
        if not collection_details:
            return []

        parts = collection_details.get(PARTS_KEY, [])
        movie_titles = []
        for movie in parts:
            title = movie.get(NAME_KEY)
            if title is None:
                title = movie.get("original_name", "")
            release_date = movie.get("release_date")
            movie_titles.append({
                "title": title,
                "release_date": release_date,
            })
        return movie_titles
    except Exception as exc:
        raise RuntimeError(f"Failed to extract movies from collection details: {exc}") from exc


def main():
    matched_collection_list = search_for_collection()
    collection_identifier = select_matched_collection(matched_collection_list)
    collection_details = retrieve_collection_details(collection_identifier)
    movie_list = extract_movies_from_collection(collection_details)
    return movie_list


if __name__ == "__main__":
    try:
        movie_list = main()
        print(f"Movies in '{COLLECTION_QUERY}' collection:")
        if not movie_list:
            print("No movies found.")
        else:
            for idx, movie in enumerate(movie_list, start=1):
                title = movie.get("title", "Unknown title")
                release_date = movie.get("release_date")
                if release_date:
                    print(f"{idx}. {title} ({release_date})")
                else:
                    print(f"{idx}. {title}")
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_collections import Search_collections
from Search_movie import Search_movie
from Get_movie_reviews import Get_movie_reviews

import traceback

COLLECTION_QUERY = "The Fast and the Furious"
MOVIE_SEARCH_QUERY = "The Fast and the Furious"
MAX_REVIEW_CHARS = 1200


def safe_get(dct, path, default=None):
    current = dct
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


def choose_matching_collection(collection_results):
    results = collection_results.get("results", [])
    if not results:
        return None

    query_lower = COLLECTION_QUERY.lower()
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if query_lower in name or query_lower in original_name or name in query_lower or original_name in query_lower:
            return item
    return results[0]


def choose_matching_movie(movie_results, collection_reference):
    results = movie_results.get("results", [])
    if not results:
        return None

    collection_name = ""
    if isinstance(collection_reference, dict):
        collection_name = str(collection_reference.get("name", "")).lower()

    query_lower = MOVIE_SEARCH_QUERY.lower()
    for item in results:
        title = str(item.get("title", "")).lower()
        original_title = str(item.get("original_title", "")).lower()
        if query_lower in title or query_lower in original_title or title in query_lower or original_title in query_lower:
            return item

    if collection_name:
        for item in results:
            title = str(item.get("title", "")).lower()
            original_title = str(item.get("original_title", "")).lower()
            if collection_name in title or collection_name in original_title:
                return item

    return results[0]


def find_collection_movie(collection_query):
    collection_results = Search_collections(collection_query)
    selected_collection = choose_matching_collection(collection_results)
    return selected_collection


def find_movie_in_collection(collection_reference):
    movie_results = Search_movie(MOVIE_SEARCH_QUERY)
    selected_movie = choose_matching_movie(movie_results, collection_reference)
    return selected_movie


def retrieve_movie_reviews(movie_reference):
    if not movie_reference:
        return None
    movie_id = movie_reference.get("id")
    if movie_id is None:
        return None
    review_results = Get_movie_reviews(movie_id)
    return review_results


def summarize_reviews(review_results, movie_reference=None):
    if not review_results:
        title = movie_reference.get("title") if isinstance(movie_reference, dict) else MOVIE_SEARCH_QUERY
        return f"No reviews were found for '{title}'."

    results = review_results.get("results", [])
    title = movie_reference.get("title") if isinstance(movie_reference, dict) else f"movie ID {review_results.get('id', 'unknown')}"

    if not results:
        return f"No reviews were found for '{title}'."

    lines = [f"Reviews for '{title}':", ""]
    for idx, review in enumerate(results[:3], start=1):
        author = review.get("author", "Unknown author")
        content = str(review.get("content", "")).strip().replace("\r", " ").replace("\n", " ")
        if len(content) > MAX_REVIEW_CHARS:
            content = content[:MAX_REVIEW_CHARS].rstrip() + "..."
        rating = safe_get(review, ["author_details", "rating"], None)
        rating_text = f"Rating: {rating}" if rating is not None else "Rating: N/A"
        lines.append(f"{idx}. {author} ({rating_text})")
        lines.append(f"   {content}")
        lines.append("")

    return "\n".join(lines).strip()


def main():
    collection_reference = find_collection_movie(COLLECTION_QUERY)
    movie_reference = find_movie_in_collection(collection_reference)
    review_results = retrieve_movie_reviews(movie_reference)
    final_review = summarize_reviews(review_results, movie_reference)

    print(final_review)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_collections import Search_collections
from Get_collection_details import Get_collection_details

import traceback

COLLECTION_NAME_QUERY = "Lord of the Rings"


def normalize_api_text(text):
    return str(text).replace("®", "").replace("™", "").replace("©", "").strip().lower()


def search_collection_by_name(collection_name):
    if collection_name is None:
        raise ValueError("collection_name is required")
    return Search_collections(collection_name)


def select_best_collection(collection_search_results):
    results = collection_search_results.get("results", [])
    if not results:
        return None

    target = normalize_api_text(COLLECTION_NAME_QUERY)
    for item in results:
        name = normalize_api_text(item.get("name", ""))
        original_name = normalize_api_text(item.get("original_name", ""))
        if target in name or target in original_name:
            return item

    return results[0]


def get_collection_details_by_id(collection_entry):
    if not collection_entry or "id" not in collection_entry:
        return None
    return Get_collection_details(collection_entry["id"])


def identify_first_movie(collection_details):
    if not collection_details:
        return None

    parts = collection_details.get("parts", [])
    if not parts:
        return None

    def sort_key(part):
        release_date = part.get("release_date")
        return (release_date is None, release_date or "9999-12-31", part.get("id", 0))

    ordered_parts = sorted(parts, key=sort_key)
    return ordered_parts[0]


def format_answer(movie_entry):
    if not movie_entry:
        return "No movie found in the collection."

    release_date = movie_entry.get("release_date")
    movie_name = movie_entry.get("name", "Unknown title")
    if release_date:
        return f"The first movie in the Lord of the Rings collection is '{movie_name}', released on {release_date}."
    return f"The first movie in the Lord of the Rings collection is '{movie_name}', but its release date is unavailable."


def main():
    collection_results = search_collection_by_name(COLLECTION_NAME_QUERY)
    selected_collection = select_best_collection(collection_results)
    if selected_collection is None:
        raise Exception("No matching collection found.")
    collection_details = get_collection_details_by_id(selected_collection)
    if collection_details is None:
        raise Exception("Collection details could not be retrieved.")
    first_movie = identify_first_movie(collection_details)
    if first_movie is None:
        raise Exception("No movie found in the collection parts.")
    print(format_answer(first_movie))


