from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_credits import Get_tv_season_credits

TMDB_SEARCH_QUERY = "House of Cards"
TARGET_SERIES_NAME = "House of Cards"
FIRST_SEASON_NUMBER = 1


def search_series(title_query):
    if title_query is None:
        raise ValueError("title_query is required.")
    return Search_tv(title_query)


def get_series_details(series_id):
    if series_id is None:
        raise ValueError("series_id is required.")
    return Get_tv_details(series_id)


def get_season_credits(series_id, season_number):
    if series_id is None:
        raise ValueError("series_id is required.")
    if season_number is None:
        raise ValueError("season_number is required.")
    return Get_tv_season_credits(series_id, season_number)


def select_correct_series_id(search_results, target_name):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    target_lower = str(target_name).strip().lower()
    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if target_lower in name or target_lower in original_name:
            return item.get("id")

    return results[0].get("id")


def verify_series_matches_requirement(series_details, target_name):
    if not isinstance(series_details, dict):
        return False
    name = str(series_details.get("name", "")).strip().lower()
    original_name = str(series_details.get("original_name", "")).strip().lower()
    target_lower = str(target_name).strip().lower()
    return target_lower in name or target_lower in original_name


def determine_first_season_number(series_details):
    seasons = series_details.get("seasons", []) if isinstance(series_details, dict) else []
    if not seasons:
        return FIRST_SEASON_NUMBER

    for season in seasons:
        season_number = season.get("season_number")
        if season_number == FIRST_SEASON_NUMBER:
            return season_number

    return FIRST_SEASON_NUMBER


def extract_first_season_directors(season_credits):
    directors = []
    if not isinstance(season_credits, dict):
        return directors

    crew = season_credits.get("crew", [])
    for crew_member in crew:
        job = str(crew_member.get("job", "")).strip().lower()
        department = str(crew_member.get("department", "")).strip().lower()
        if "director" in job or "director" in department:
            name = crew_member.get("name")
            if name and name not in directors:
                directors.append(name)

    return directors


def format_directors_output(series_name, directors):
    if not directors:
        return f"No directors found for season 1 of {series_name}."
    joined = ", ".join(directors)
    return f"Directors of the first season of {series_name}: {joined}"


def main():
    search_results = search_series(TMDB_SEARCH_QUERY)
    series_id = select_correct_series_id(search_results, TARGET_SERIES_NAME)

    if series_id is None:
        print(f"Could not find a matching series for: {TARGET_SERIES_NAME}")
        return

    series_details = get_series_details(series_id)
    verify_series_matches_requirement(series_details, TARGET_SERIES_NAME)

    first_season_number = determine_first_season_number(series_details)
    season_credits = get_season_credits(series_id, first_season_number)

    directors = extract_first_season_directors(season_credits)
    output = format_directors_output(series_details.get("name", TARGET_SERIES_NAME), directors)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        import sys
        import traceback

        traceback.print_exc(file=sys.stderr)
        raise

