from Get_tv_details import Get_tv_details

import traceback

RESTBENCH_TOOLS_DIR = PROJECT_ROOT / "restbench tools"


TOP_N = 1
RESULTS_KEY = "results"
POPULARITY_KEY = "popularity"
ID_KEY = "id"
FIRST_AIR_DATE_KEY = "first_air_date"
NAME_KEY = "name"


def normalize_api_text(value):
    if value is None:
        return ""
    text = str(value)
    for ch in ("®", "™", "©"):
        text = text.replace(ch, "")
    return text.strip().lower()


def fetch_current_on_air_shows():
    data = Get_on_the_air_tv()
    if not isinstance(data, dict):
        raise Exception("Expected Get_on_the_air_tv() to return a dictionary.")
    return data


def select_most_popular_show(show_list_response):
    results = show_list_response.get(RESULTS_KEY, [])
    if not isinstance(results, list) or len(results) == 0:
        return None

    def popularity_value(item):
        value = item.get(POPULARITY_KEY, 0)
        return value if isinstance(value, (int, float)) else 0

    sorted_results = sorted(results, key=popularity_value, reverse=True)
    return sorted_results[0] if sorted_results else None


def fetch_show_details(series_id):
    if series_id is None:
        raise Exception("`series_id` is required.")
    data = Get_tv_details(series_id)
    if not isinstance(data, dict):
        raise Exception("Expected Get_tv_details() to return a dictionary.")
    return data


def extract_start_date(show_details):
    return show_details.get(FIRST_AIR_DATE_KEY)


def build_result_message(show_details, start_date):
    show_name = show_details.get(NAME_KEY, "Unknown show")
    if start_date:
        return f"The most popular TV show currently on the air is '{show_name}', and it started on {start_date}."
    return f"The most popular TV show currently on the air is '{show_name}', but its start date was not available."


def main():
    on_air_response = fetch_current_on_air_shows()
    top_show = select_most_popular_show(on_air_response)

    if top_show is None:
        raise Exception("No currently on-air TV shows were returned by the API.")

    series_id = top_show.get(ID_KEY)
    if series_id is None:
        raise Exception("The most popular on-air show did not include an ID.")

    show_details = fetch_show_details(series_id)
    start_date = extract_start_date(show_details)
    message = build_result_message(show_details, start_date)
    print(message)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

