from Search_tv import Search_tv
from Get_tv_recommendations import Get_tv_recommendations

import traceback

SHOW_NAME = "The Last Of Us"
TARGET_NAME_MAPPING = {
    "search_target": SHOW_NAME,
    "display_target": SHOW_NAME,
}
TOP_N_RECOMMENDATIONS = 10


def search_for_tv_show_by_name(show_name):
    try:
        return Search_tv(query=show_name)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV show '{show_name}': {exc}")


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def choose_best_match(search_results, target_name):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    target_norm = normalize_text(target_name)
    exact_candidates = []
    partial_candidates = []

    for item in results:
        name = normalize_text(item.get("name"))
        original_name = normalize_text(item.get("original_name"))
        if target_norm and (target_norm in name or target_norm in original_name):
            partial_candidates.append(item)
        if target_norm and (name == target_norm or original_name == target_norm):
            exact_candidates.append(item)

    if exact_candidates:
        return max(exact_candidates, key=lambda x: x.get("vote_count", 0) or 0)
    if partial_candidates:
        return max(partial_candidates, key=lambda x: x.get("vote_count", 0) or 0)

    return max(results, key=lambda x: x.get("vote_count", 0) or 0)


def select_matching_show_id(search_results, target_name):
    matching_show = choose_best_match(search_results, target_name=target_name)
    if not matching_show:
        raise RuntimeError(f"No TV show results found for '{target_name}'.")
    show_id = matching_show.get("id")
    if show_id is None:
        raise RuntimeError("Matched TV show is missing an 'id' field.")
    return show_id, matching_show


def fetch_tv_recommendations(show_id):
    try:
        return Get_tv_recommendations(series_id=show_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch recommendations for TV show id {show_id}: {exc}")


def curate_recommendations(recommendations, top_n):
    results = recommendations.get("results", []) if isinstance(recommendations, dict) else []
    curated = []

    for item in results[:top_n]:
        curated.append(
            {
                "name": item.get("name", ""),
                "first_air_date": item.get("first_air_date", ""),
                "vote_average": item.get("vote_average", None),
                "overview": item.get("overview", ""),
                "id": item.get("id", None),
            }
        )
    return curated


def format_recommendation_output(source_show, recommendations, curated_results):
    lines = []
    lines.append(f"Because you're watching: {source_show.get('name', SHOW_NAME)}")
    lines.append("Here are some TV show recommendations:")
    if not curated_results:
        lines.append("No recommendations were returned.")
        return "\n".join(lines)

    for idx, item in enumerate(curated_results, start=1):
        title = item.get("name") or "Unknown title"
        date = item.get("first_air_date") or "Unknown date"
        rating = item.get("vote_average")
        rating_text = f"{rating:.1f}" if isinstance(rating, (int, float)) else "N/A"
        overview = item.get("overview") or "No overview available."
        lines.append(f"{idx}. {title} ({date}) - Rating: {rating_text}")
        lines.append(f"   {overview}")
    return "\n".join(lines)


def main():
    search_results = search_for_tv_show_by_name(TARGET_NAME_MAPPING["search_target"])
    show_id, source_show = select_matching_show_id(search_results, TARGET_NAME_MAPPING["search_target"])
    recommendations = fetch_tv_recommendations(show_id)
    curated_results = curate_recommendations(recommendations, TOP_N_RECOMMENDATIONS)
    final_output = format_recommendation_output(source_show, recommendations, curated_results)
    print(final_output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_tv import Search_tv
from Get_tv_recommendations import Get_tv_recommendations

import traceback

TARGET_TITLE = "The Last Of Us"
MAX_RECOMMENDATIONS = 10
MIN_NAME_MATCH_SCORE = 0.55


def _safe_get_text(value):
    return "" if value is None else str(value)


def _normalize_text(text):
    return "".join(ch.lower() for ch in _safe_get_text(text) if ch.isalnum() or ch.isspace()).strip()


def _tokenize(text):
    return [tok for tok in _normalize_text(text).split() if tok]


def _jaccard_similarity(a, b):
    set_a = set(_tokenize(a))
    set_b = set(_tokenize(b))
    if not set_a or not set_b:
        return 0.0
    return len(set_a & set_b) / len(set_a | set_b)


def choose_best_matching_show(search_results, target_title):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    best_item = None
    best_score = -1.0
    target_norm = _normalize_text(target_title)

    for item in results:
        name = item.get("name", "")
        original_name = item.get("original_name", "")
        score = max(
            _jaccard_similarity(target_norm, name),
            _jaccard_similarity(target_norm, original_name),
        )
        if target_norm in _normalize_text(name) or target_norm in _normalize_text(original_name):
            score += 0.5
        if score > best_score:
            best_score = score
            best_item = item

    if best_item is None:
        best_item = results[0]
    return best_item


def Search_Show_By_Title(query_title):
    search_results = Search_tv(query_title)
    selected_show = choose_best_matching_show(search_results, query_title)
    if not selected_show:
        return None
    return selected_show.get("id")


def Fetch_Show_Recommendations(show_identifier):
    if show_identifier is None:
        return {"page": 0, "results": [], "total_pages": 0, "total_results": 0}
    return Get_tv_recommendations(show_identifier)


def _deduplicate_by_id(recommendation_list):
    seen = set()
    deduped = []
    for item in recommendation_list:
        item_id = item.get("id")
        if item_id in seen:
            continue
        seen.add(item_id)
        deduped.append(item)
    return deduped


def _sort_recommendations(recommendation_list):
    return sorted(
        recommendation_list,
        key=lambda x: (
            -(x.get("vote_average") or 0),
            -(x.get("popularity") or 0),
            _safe_get_text(x.get("name")),
        ),
    )


def Normalize_Recommendations(recommendation_results):
    recommendation_list = recommendation_results.get("results", []) if isinstance(recommendation_results, dict) else []
    recommendation_list = [item for item in recommendation_list if isinstance(item, dict)]
    recommendation_list = _deduplicate_by_id(recommendation_list)
    recommendation_list = _sort_recommendations(recommendation_list)
    return recommendation_list[:MAX_RECOMMENDATIONS]


def format_recommendations(recommendations):
    if not recommendations:
        return f"No recommendations found for {TARGET_TITLE}."

    lines = [f"Recommendations similar to '{TARGET_TITLE}':"]
    for idx, item in enumerate(recommendations, start=1):
        name = item.get("name", "Unknown title")
        first_air_date = item.get("first_air_date", "Unknown date")
        vote_average = item.get("vote_average", "N/A")
        overview = item.get("overview", "").strip()
        if len(overview) > 160:
            overview = overview[:157].rstrip() + "..."
        lines.append(f"{idx}. {name} ({first_air_date}) - Rating: {vote_average}")
        if overview:
            lines.append(f"   {overview}")
    return "\n".join(lines)


def run():
    show_id = Search_Show_By_Title(TARGET_TITLE)
    raw_recommendations = Fetch_Show_Recommendations(show_id)
    final_recommendations = Normalize_Recommendations(raw_recommendations)
    return format_recommendations(final_recommendations)


if __name__ == "__main__":
    try:
        output = run()
        print(output)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

