from Search_tv import Search_tv
from Get_tv_episode_credits import Get_tv_episode_credits

import traceback

# Module-level pinned constants derived from the user requirement and API schema.
TARGET_SHOW_QUERY = "Friends"
TARGET_SEASON_NUMBER = 3
TARGET_EPISODE_NUMBER = 24


def search_show(query):
    """
    Search for the target TV show and return the best matching show record.
    Uses API: Search_tv(query)
    """
    try:
        response = Search_tv(query)
    except Exception as exc:
        raise RuntimeError(f"TV show search failed: {exc}") from exc

    results = response.get("results", [])
    if not results:
        return None

    query_lower = query.lower()
    # Prefer an exact-ish name match, but avoid strict equality-only logic.
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if query_lower in name or query_lower in original_name:
            return item

    return results[0]


def get_episode_credits(series_id, season_number, episode_number):
    """
    Retrieve episode credits for a given show/season/episode.
    Uses API: Get_tv_episode_credits(series_id, season_number, episode_number)
    """
    try:
        return Get_tv_episode_credits(series_id, season_number, episode_number)
    except Exception as exc:
        raise RuntimeError(
            f"Episode credits lookup failed for series_id={series_id}, "
            f"season={season_number}, episode={episode_number}: {exc}"
        ) from exc


def extract_guest_stars(episode_credits):
    """
    Extract guest star entries from the episode credits response.
    Schema-grounded key: 'guest_stars'
    """
    guest_stars = episode_credits.get("guest_stars", [])
    extracted = []
    for person in guest_stars:
        extracted.append(
            {
                "name": person.get("name"),
                "character": person.get("character"),
                "order": person.get("order"),
            }
        )
    return extracted


def format_guest_star_output(guest_stars):
    """
    Create a readable, task-oriented string for printing.
    """
    if not guest_stars:
        return "No guest stars found for Friends season 3, episode 24."

    lines = ["Guest stars for Friends season 3, episode 24:"]
    for idx, person in enumerate(guest_stars, start=1):
        name = person.get("name") or "Unknown"
        character = person.get("character") or "Unknown character"
        lines.append(f"{idx}. {name} as {character}")
    return "\n".join(lines)


def main():
    show = search_show(TARGET_SHOW_QUERY)
    if not show:
        print(f"No TV show results found for {TARGET_SHOW_QUERY}.")
        return

    series_id = show.get("id")
    if series_id is None:
        print(f"Could not determine show ID for {TARGET_SHOW_QUERY}.")
        return

    episode_credits = get_episode_credits(
        series_id, TARGET_SEASON_NUMBER, TARGET_EPISODE_NUMBER
    )
    guest_stars = extract_guest_stars(episode_credits)
    print(format_guest_star_output(guest_stars))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

