from Search_tv import Search_tv
from Get_tv_images import Get_tv_images

import traceback

SHOW_QUERY = "2 Broke Girls"
POSTER_PREFERRED_MIN_WIDTH = 500
POSTER_PREFERRED_MIN_HEIGHT = 750


def search_show_title():
    try:
        return Search_tv(SHOW_QUERY)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV show '{SHOW_QUERY}': {exc}") from exc


def select_show_identifier(search_results):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    query_lower = SHOW_QUERY.lower()
    for show in results:
        name = str(show.get("name", "")).lower()
        original_name = str(show.get("original_name", "")).lower()
        if query_lower in name or query_lower in original_name:
            return show.get("id")

    return results[0].get("id")


def retrieve_show_images(show_identifier):
    if show_identifier is None:
        return {"backdrops": [], "logos": [], "posters": [], "id": None}
    try:
        return Get_tv_images(show_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve images for show id {show_identifier}: {exc}") from exc


def choose_poster_image(image_assets):
    posters = image_assets.get("posters", []) if isinstance(image_assets, dict) else []
    if not posters:
        return None

    def score(poster):
        width = poster.get("width") or 0
        height = poster.get("height") or 0
        votes = poster.get("vote_count") or 0
        avg = poster.get("vote_average") or 0
        iso = poster.get("iso_639_1")
        language_bonus = 10 if iso in ("en", None) else 0
        size_bonus = 1 if width >= POSTER_PREFERRED_MIN_WIDTH and height >= POSTER_PREFERRED_MIN_HEIGHT else 0
        return (size_bonus * 1000000) + (votes * 1000) + int(avg * 100) + language_bonus + width + height

    best_poster = max(posters, key=score)
    return best_poster


def format_poster_output(show_identifier, poster):
    if not poster:
        print("No poster image was found for '2 Broke Girls'.")
        return

    file_path = poster.get("file_path", "")
    print("Poster found for '2 Broke Girls':")
    print(f"Show ID: {show_identifier}")
    print(f"Poster path: {file_path}")
    if file_path:
        print(f"Poster URL: https://image.tmdb.org/t/p/original{file_path}")


def main():
    search_results = search_show_title()
    show_identifier = select_show_identifier(search_results)
    image_assets = retrieve_show_images(show_identifier)
    poster = choose_poster_image(image_assets)
    format_poster_output(show_identifier, poster)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

