from Search_tv import Search_tv
from Get_tv_details import Get_tv_details

import os
import traceback

SHOW_QUERY = "2 Broke Girls"


def search_show_id(show_query):
    try:
        search_result = Search_tv(show_query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV show '{show_query}': {exc}") from exc

    results = search_result.get("results", [])
    if not results:
        raise RuntimeError(f"No TV show results found for query: {show_query}")

    # Prefer an exact-ish name match using lenient normalization.
    normalized_query = str(show_query).strip().lower()
    matched = None
    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if normalized_query in name or normalized_query in original_name:
            matched = item
            break

    if matched is None:
        matched = results[0]

    series_id = matched.get("id")
    if series_id is None:
        raise RuntimeError(f"Selected search result has no 'id' field for query: {show_query}")

    return series_id


def get_show_details(show_id):
    try:
        return Get_tv_details(show_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch TV show details for ID {show_id}: {exc}") from exc


def extract_total_episodes(show_details):
    total_episodes = show_details.get("number_of_episodes")
    if total_episodes is None:
        raise RuntimeError("TV show details did not include 'number_of_episodes'.")
    return total_episodes


def main():
    show_id = search_show_id(SHOW_QUERY)
    show_details = get_show_details(show_id)
    total_episodes = extract_total_episodes(show_details)
    print(f"{SHOW_QUERY} has {total_episodes} episodes in total.")


if __name__ == "__main__":
    try:
        main()
