import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_tv import Search_tv
from Get_company_details import Get_company_details

import traceback

# Module-level pinned constants
TARGET_SHOW_NAME = "The Big Bang Theory"
COMPANY_NAME_FIELD = "name"
COMPANY_ID_FIELD = "id"
SHOW_RESULTS_FIELD = "results"
SHOW_NAME_FIELD = "name"
SHOW_ID_FIELD = "id"
COMPANY_FOUNDING_HINT_FIELDS = ("description", "headquarters", "homepage", "parent_company", "origin_country")

def locate_target_show(show_query):
    try:
        search_results = Search_tv(show_query)
        return select_best_match(search_results, show_query)
    except Exception as exc:
        raise RuntimeError(f"Failed to locate target show: {exc}") from exc

def select_best_match(search_results, query):
    results = search_results.get(SHOW_RESULTS_FIELD, [])
    if not results:
        return None

    query_lower = str(query).lower()
    for item in results:
        name = str(item.get(SHOW_NAME_FIELD, ""))
        if query_lower in name.lower() or name.lower() in query_lower:
            return item

    return results[0]

def resolve_show_identifier(matching_show):
    if not matching_show:
        return None
    return matching_show.get(SHOW_ID_FIELD)

def retrieve_show_details(show_id):
    # No Get_tv_details API provided in the prompt; keep modular placeholder behavior.
    return {"id": show_id, "production_companies": []}

def extract_production_company_references(show_details):
    production_companies = show_details.get("production_companies", [])
    if not production_companies:
        return None
    first_company = production_companies[0]
    return first_company.get(COMPANY_NAME_FIELD) or first_company.get(COMPANY_ID_FIELD)

def locate_company(company_reference):
    # No Search_company API provided in the prompt; use the reference directly when possible.
    if company_reference is None:
        return None
    if isinstance(company_reference, dict):
        return company_reference
    return {COMPANY_NAME_FIELD: company_reference}

def resolve_company_identifier(matching_company):
    if not matching_company:
        return None
    return matching_company.get(COMPANY_ID_FIELD)

def retrieve_company_details(company_id):
    try:
        return Get_company_details(company_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve company details: {exc}") from exc

def derive_founding_information(company_details):
    company_name = company_details.get(COMPANY_NAME_FIELD, "Unknown company")
    founded_text = infer_founding_information_from_available_company_fields(company_details)
    return f"{company_name} was founded {founded_text}"

def infer_founding_information_from_available_company_fields(company_details):
    # TMDB company details schema does not include a founding date field.
    # We therefore provide the best supported answer from available data.
    homepage = company_details.get("homepage")
    origin_country = company_details.get("origin_country")
    description = company_details.get("description")

    parts = []
    if origin_country:
        parts.append(f"in origin country {origin_country}")
    if homepage:
        parts.append(f"Homepage: {homepage}")
    if description:
        parts.append(f"Description: {description}")

    if not parts:
        return "at an unknown founding date (the provided API does not include founding year/date)"
    return "at an unknown founding date (the provided API does not include founding year/date). " + " ".join(parts)

def main():
    matched_show = locate_target_show(TARGET_SHOW_NAME)
    show_id = resolve_show_identifier(matched_show)
    show_details = retrieve_show_details(show_id)

    company_reference = extract_production_company_references(show_details)
    matched_company = locate_company(company_reference)
    company_id = resolve_company_identifier(matched_company)

    if company_id is None:
        # Since no company-search API is available in the provided API list,
        # we make a best-effort attempt only if a direct ID exists.
        company_details = {
            "name": company_reference if isinstance(company_reference, str) else "Unknown company",
            "homepage": "",
            "origin_country": "",
            "description": "",
            "headquarters": "",
            "parent_company": None,
            "id": None,
            "logo_path": "",
        }
    else:
        company_details = retrieve_company_details(company_id)

    founding_information = derive_founding_information(company_details)
    print(founding_information)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

