from Search_tv import Search_tv
from Get_tv_details import Get_tv_details

import traceback

TV_SHOW_TITLE = "The Big Bang Theory"


def search_tv_show_by_title(title):
    try:
        return Search_tv(title)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV show '{title}': {exc}")


def select_matching_tv_show(search_results, title):
    results = search_results.get("results", [])
    if not results:
        return None

    normalized_title = title.strip().lower()

    def score(result):
        name = str(result.get("name", "")).strip().lower()
        original_name = str(result.get("original_name", "")).strip().lower()
        exact_match = 0
        if name == normalized_title or original_name == normalized_title:
            exact_match = 100
        elif normalized_title in name or normalized_title in original_name:
            exact_match = 80
        return (
            exact_match,
            float(result.get("vote_count", 0)),
            float(result.get("popularity", 0)),
        )

    best_match = max(results, key=score)
    return best_match.get("id")


def get_tv_show_details(tv_show_id):
    if tv_show_id is None:
        return None
    try:
        return Get_tv_details(tv_show_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to get TV show details for id '{tv_show_id}': {exc}")


def extract_creation_date(tv_details):
    if not tv_details:
        return None
    return tv_details.get("first_air_date")


def format_output(title, creation_date):
    if creation_date:
        return f"The TV show '{title}' was created/first aired on {creation_date}."
    return f"Could not determine when the TV show '{title}' was created."


def main():
    search_results = search_tv_show_by_title(TV_SHOW_TITLE)
    tv_show_id = select_matching_tv_show(search_results, TV_SHOW_TITLE)
    tv_details = get_tv_show_details(tv_show_id)
    creation_date = extract_creation_date(tv_details)
    print(format_output(TV_SHOW_TITLE, creation_date))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

