from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_details import Get_tv_season_details
from Get_tv_episode_details import Get_tv_episode_details

import traceback

TMDB_SERIES_QUERY = "Westworld"
TMDB_SEASON_NUMBER = 2
TMDB_EPISODE_NUMBER = 3
EPISODE_INDEX_BASE = 1


def search_series(series_query):
    if not series_query:
        raise ValueError("series_query must be provided")
    return Search_tv(series_query)


def get_series_details(series_id):
    if series_id is None:
        raise ValueError("series_id must be provided")
    return Get_tv_details(series_id)


def get_season_details(series_id, season_number):
    if series_id is None:
        raise ValueError("series_id must be provided")
    if season_number is None:
        raise ValueError("season_number must be provided")
    return Get_tv_season_details(series_id, season_number)


def get_episode_details(series_id, season_number, episode_number):
    if series_id is None:
        raise ValueError("series_id must be provided")
    if season_number is None:
        raise ValueError("season_number must be provided")
    if episode_number is None:
        raise ValueError("episode_number must be provided")
    return Get_tv_episode_details(series_id, season_number, episode_number)


def extract_relevant_series(search_result, requested_name):
    results = search_result.get("results", [])
    if not results:
        raise ValueError(f"No TV series results found for query: {requested_name}")

    requested_lower = requested_name.lower()
    best_match = None

    for item in results:
        name = str(item.get("name", ""))
        original_name = str(item.get("original_name", ""))
        if requested_lower in name.lower() or requested_lower in original_name.lower():
            best_match = item
            break

    if best_match is None:
        best_match = results[0]

    series_id = best_match.get("id")
    if series_id is None:
        raise ValueError("Matched series result did not contain an id")
    return series_id, best_match


def confirm_series(details_result, requested_name):
    name = str(details_result.get("name", ""))
    original_name = str(details_result.get("original_name", ""))
    matched = requested_name.lower() in name.lower() or requested_name.lower() in original_name.lower()
    return matched


def identify_season(season_result, requested_season_number):
    season_number = season_result.get("season_number")
    episodes = season_result.get("episodes", [])
    episode_count = len(episodes)
    return {
        "season_number": season_number,
        "episode_count": episode_count,
        "requested_season_number": requested_season_number,
    }


def identify_episode(episode_result):
    overview = episode_result.get("overview", "")
    name = episode_result.get("name", "")
    episode_number = episode_result.get("episode_number")
    season_number = episode_result.get("season_number")
    return {
        "name": name,
        "overview": overview,
        "episode_number": episode_number,
        "season_number": season_number,
    }


def format_output(series_name, season_number, episode_number, episode_info):
    episode_title = episode_info.get("name", "Unknown episode")
    overview = episode_info.get("overview", "")
    if overview:
        return (
            f"{series_name} - Season {season_number}, Episode {episode_number} "
            f"('{episode_title}') was about:\n{overview}"
        )
    return (
        f"{series_name} - Season {season_number}, Episode {episode_number} "
        f"('{episode_title}') did not include an overview."
    )


def main():
    search_result = search_series(TMDB_SERIES_QUERY)
    series_id, _ = extract_relevant_series(search_result, TMDB_SERIES_QUERY)

    series_details = get_series_details(series_id)
    confirm_series(series_details, TMDB_SERIES_QUERY)

    season_details = get_season_details(series_id, TMDB_SEASON_NUMBER)
    identify_season(season_details, TMDB_SEASON_NUMBER)

    episode_details = get_episode_details(series_id, TMDB_SEASON_NUMBER, TMDB_EPISODE_NUMBER)
    episode_info = identify_episode(episode_details)

    output = format_output(TMDB_SERIES_QUERY, TMDB_SEASON_NUMBER, TMDB_EPISODE_NUMBER, episode_info)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

