import traceback

TARGET_TITLE = "Game of Thrones"
TARGET_SEASON_NUMBER = 2


def search_show(series_query):
    if not series_query:
        raise ValueError("series_query is required.")
    return Search_tv(series_query)


def select_show_identifier(search_results, target_title):
    results = search_results.get("results", [])
    if not results:
        return None

    normalized_target = target_title.strip().lower()
    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if normalized_target in name or normalized_target in original_name:
            return item.get("id")

    return results[0].get("id")


def get_show_details(show_id):
    if show_id is None:
        return None
    return Get_tv_details(show_id)


def select_second_season_identifier(show_details):
    seasons = show_details.get("seasons", [])
    if not seasons:
        return None

    for season in seasons:
        season_number = season.get("season_number")
        if season_number is not None and season_number == TARGET_SEASON_NUMBER:
            return season.get("season_number")

    return None


def get_second_season_details(show_id, season_number):
    if show_id is None or season_number is None:
        return None
    return Get_tv_season_details(show_id, season_number)


def extract_air_date(season_details):
    if not season_details:
        return None
    return season_details.get("air_date")


def build_air_date_response():
    search_results = search_show(TARGET_TITLE)
    show_id = select_show_identifier(search_results, TARGET_TITLE)
    show_details = get_show_details(show_id)
    season_number = select_second_season_identifier(show_details)
    season_details = get_second_season_details(show_id, season_number)
    air_date = extract_air_date(season_details)
    return air_date


def main():
    air_date = build_air_date_response()
    if air_date:
        print(f"Air date of the second season of {TARGET_TITLE}: {air_date}")
    else:
        print(f"Air date of the second season of {TARGET_TITLE}: not found")


if __name__ == "__main__":
