from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_episode_details import Get_tv_episode_details
from Get_tv_episode_images import Get_tv_episode_images

import traceback

SERIES_QUERY = "Band of Brothers"
TARGET_EPISODE_NUMBER = 3
BASE_IMAGE_URL = "https://image.tmdb.org/t/p/original"


def safe_get(d, *keys, default=None):
    current = d
    for key in keys:
        if not isinstance(current, dict):
            return default
        current = current.get(key, default)
        if current is default:
            return default
    return current


def search_series(series_query):
    try:
        return Search_tv(query=series_query)
    except Exception:
        raise


def choose_correct_series_id(search_response):
    results = search_response.get("results", []) if isinstance(search_response, dict) else []
    target = SERIES_QUERY.lower()
    best_match = None

    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if target in name or target in original_name:
            best_match = item
            break

    if best_match is None and results:
        best_match = results[0]

    if not best_match:
        raise ValueError("No TV series search results found.")

    return best_match.get("id")


def get_series_details(series_id):
    return Get_tv_details(series_id=series_id)


def choose_third_episode_season(series_details):
    seasons = series_details.get("seasons", []) if isinstance(series_details, dict) else []
    candidate_seasons = []

    for season in seasons:
        season_number = season.get("season_number")
        episode_count = season.get("episode_count", 0)
        if isinstance(season_number, int) and isinstance(episode_count, int) and episode_count >= TARGET_EPISODE_NUMBER:
            candidate_seasons.append(season)

    if candidate_seasons:
        return candidate_seasons[0].get("season_number")

    raise ValueError("No season contains the third episode.")


def get_episode_details(series_id, season_number, episode_number):
    return Get_tv_episode_details(
        series_id=series_id,
        season_number=season_number,
        episode_number=episode_number,
    )


def get_episode_images(series_id, season_number, episode_number):
    return Get_tv_episode_images(
        series_id=series_id,
        season_number=season_number,
        episode_number=episode_number,
    )


def select_poster_like_image(episode_images):
    stills = episode_images.get("stills", []) if isinstance(episode_images, dict) else []
    if not stills:
        return None

    best = None
    best_score = None

    for still in stills:
        width = still.get("width", 0) or 0
        height = still.get("height", 0) or 0
        aspect = still.get("aspect_ratio", 0) or 0
        score = (width * height, aspect)

        if best is None or score > best_score:
            best = still
            best_score = score

    return best


def build_output(episode_details, poster_asset):
    poster_path = None
    if isinstance(poster_asset, dict):
        poster_path = poster_asset.get("file_path")

    return {
        "series_name": SERIES_QUERY,
        "episode_number": episode_details.get("episode_number") if isinstance(episode_details, dict) else TARGET_EPISODE_NUMBER,
        "episode_name": episode_details.get("name") if isinstance(episode_details, dict) else None,
        "poster_path": poster_path,
        "poster_url": f"{BASE_IMAGE_URL}{poster_path}" if poster_path else None,
    }


def main():
    search_response = search_series(SERIES_QUERY)
    series_id = choose_correct_series_id(search_response)
    series_details = get_series_details(series_id)
    season_number = choose_third_episode_season(series_details)
    episode_details = get_episode_details(series_id, season_number, TARGET_EPISODE_NUMBER)
    episode_images = get_episode_images(series_id, season_number, TARGET_EPISODE_NUMBER)
    poster_asset = select_poster_like_image(episode_images)
    output = build_output(episode_details, poster_asset)

    print(f"Series: {output['series_name']}")
    print(f"Episode: {output['episode_number']} - {output['episode_name']}")
    if output["poster_url"]:
        print(f"Poster: {output['poster_url']}")
    else:
        print("Poster: No episode still image available.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

