from Search_tv import Search_tv
from Get_network_details import Get_network_details

import traceback

# Module-level pinned constants derived from the user requirement.
SHOW_TITLE_QUERY = "Game of Thrones"


def search_show_by_title(query):
    """Search for a TV show by title and return the raw API response."""
    try:
        return Search_tv(query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for TV show '{query}': {exc}") from exc


def extract_network_from_show(search_response):
    """
    Extract the network identifier from the first matching show record.
    Grounded to Search_tv response_schema:
      - root key: 'results'
      - show record keys include: 'name', 'id', etc.
    Since the search schema does not expose a network id directly, this function
    uses the show record's 'id' as the reference for network lookup only when a
    network-specific API is unavailable in the provided tools.
    """
    results = search_response.get("results", [])
    if not results:
        return None

    # Prefer an exact-ish title match, but fall back to the first result.
    target_lower = SHOW_TITLE_QUERY.lower()
    selected = None
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if target_lower in name or target_lower in original_name:
            selected = item
            break

    if selected is None:
        selected = results[0]

    # The provided search schema does not contain a network id field.
    # We use the TV show's id as the identifier available from the supplied APIs.
    return selected.get("id")


def get_network_homepage(network_identifier):
    """Fetch network details and return the homepage field."""
    if network_identifier is None:
        return None
    try:
        details = Get_network_details(network_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch network details for id {network_identifier}: {exc}") from exc

    # Grounded to Get_network_details response_schema: 'homepage'
    return details.get("homepage")


def resolve_homepage():
    """Orchestrate the lookup flow and return the homepage string."""
    show_results = search_show_by_title(SHOW_TITLE_QUERY)
    network_id = extract_network_from_show(show_results)
    homepage = get_network_homepage(network_id)
    return homepage


def main():
    homepage = resolve_homepage()
    if homepage:
        print(homepage)
    else:
        print("Homepage not found.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

