if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Get_popular_tv import Get_popular_tv
from Get_tv_keywords import Get_tv_keywords

import traceback

# Hardcoded constants derived from the user requirement and schema-grounded selection logic.
POPULARITY_KEY = "popularity"
RESULTS_KEY = "results"
ID_KEY = "id"
NAME_KEY = "name"
KEYWORD_NAME_KEY = "name"


def find_most_popular_tv_show():
    """Fetch popular TV shows and select the most popular one."""
    popular_data = Get_popular_tv()
    results = popular_data.get(RESULTS_KEY, []) if isinstance(popular_data, dict) else []

    if not results:
        return None

    # Schema-grounded: "popularity" is the exact key available for ranking.
    return max(results, key=lambda item: item.get(POPULARITY_KEY, 0) or 0)


def retrieve_show_keywords(show_identifier):
    """Fetch keywords for a given TV show identifier."""
    if show_identifier is None:
        return {"results": []}
    return Get_tv_keywords(show_identifier)


def select_one_keyword(keyword_data):
    """Select one keyword from keyword data, preferring the first available keyword."""
    if not isinstance(keyword_data, dict):
        return None

    keywords = keyword_data.get(RESULTS_KEY, [])
    if not keywords:
        return None

    first_keyword = keywords[0]
    return first_keyword.get(KEYWORD_NAME_KEY)


def build_output_message(show, keyword):
    """Create a readable, task-oriented output message."""
    if show is None:
        return "No TV show data available."
    show_name = show.get(NAME_KEY, "Unknown show")
    if keyword is None:
        return f"Most popular TV show currently: {show_name}\nKeyword: No keywords available"
    return f"Most popular TV show currently: {show_name}\nKeyword: {keyword}"


def main():
    show = find_most_popular_tv_show()
    if show is None:
        print("No TV show data available.")
        return

    show_identifier = show.get(ID_KEY)
    keyword_data = retrieve_show_keywords(show_identifier)
    keyword = select_one_keyword(keyword_data)
    output = build_output_message(show, keyword)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
