from Search_tv import Search_tv
from Get_tv_details import Get_tv_details

import traceback

SHOW_QUERY = "The Mandalorian"


def search_for_show_id(show_query):
    try:
        search_result = Search_tv(query=show_query)
        return search_result
    except Exception as exc:
        raise RuntimeError(f"Failed to search for TV show '{show_query}': {exc}") from exc


def extract_show_id(search_result):
    results = search_result.get("results", []) if isinstance(search_result, dict) else []
    if not results:
        return None

    target_name = SHOW_QUERY.lower()
    best_match = None

    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()

        if target_name in name or target_name in original_name:
            return item.get("id")

        if best_match is None:
            best_match = item.get("id")

    return best_match


def get_show_details(show_id):
    if show_id is None:
        return None
    try:
        show_details = Get_tv_details(series_id=show_id)
        return show_details
    except Exception as exc:
        raise RuntimeError(f"Failed to get TV show details for id {show_id}: {exc}") from exc


def extract_genre(show_details):
    if not isinstance(show_details, dict):
        return None

    genres = show_details.get("genres", [])
    if not genres:
        return None

    genre_names = []
    for genre in genres:
        name = genre.get("name")
        if name:
            genre_names.append(name)

    return genre_names


def main():
    search_result = search_for_show_id(SHOW_QUERY)
    show_id = extract_show_id(search_result)
    show_details = get_show_details(show_id)
    genres = extract_genre(show_details)

    if genres:
        print(f"Genre(s) of {SHOW_QUERY}: {', '.join(genres)}")
    else:
        print(f"Genre(s) of {SHOW_QUERY}: No genre information available")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
