from Get_trending_tv import Get_trending_tv
from Get_tv_details import Get_tv_details
from Search_person import Search_person
from Get_person_details import Get_person_details

import traceback

TRENDING_TIME_WINDOW = "day"
TOP_TV_INDEX = 0
PERSON_SEARCH_TOP_INDEX = 0


def safe_get(data, path, default=None):
    current = data
    for key in path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return default
    return current


def get_most_trending_tv_show():
    trending = Get_trending_tv(TRENDING_TIME_WINDOW)
    results = trending.get("results", []) if isinstance(trending, dict) else []
    if not results:
        return None
    if len(results) <= TOP_TV_INDEX:
        return None
    return results[TOP_TV_INDEX]


def get_tv_show_details(show_item):
    if not isinstance(show_item, dict):
        return None
    show_id = show_item.get("id")
    if show_id is None:
        return None
    return Get_tv_details(show_id)


def determine_lead_actor(show_details):
    if not isinstance(show_details, dict):
        return None
    show_name = show_details.get("name", "")
    if show_name:
        print(f"Trending TV show: {show_name}")
    else:
        print("Trending TV show: N/A")

    print(f"Show first air date: {show_details.get('first_air_date', 'N/A')}")

    actor_name = None
    search_terms = []
    for key in ("created_by", "networks", "production_companies"):
        items = show_details.get(key, [])
        if isinstance(items, list) and items:
            for item in items:
                if isinstance(item, dict):
                    candidate = item.get("name")
                    if candidate:
                        search_terms.append(candidate)

    for term in search_terms:
        person_matches = Search_person(term)
        results = person_matches.get("results", []) if isinstance(person_matches, dict) else []
        if results:
            actor_name = results[PERSON_SEARCH_TOP_INDEX].get("name")
            if actor_name:
                break

    if actor_name is None:
        fallback_title = show_details.get("name")
        if fallback_title:
            person_matches = Search_person(fallback_title)
            results = person_matches.get("results", []) if isinstance(person_matches, dict) else []
            if results:
                actor_name = results[PERSON_SEARCH_TOP_INDEX].get("name")

    return actor_name


def find_person_record(actor_name):
    if not actor_name:
        return None
    matches = Search_person(actor_name)
    results = matches.get("results", []) if isinstance(matches, dict) else []
    if not results:
        return None
    return results[PERSON_SEARCH_TOP_INDEX]


def get_actor_birthday(person_item):
    if not isinstance(person_item, dict):
        return None
    person_id = person_item.get("id")
    if person_id is None:
        return None
    person_details = Get_person_details(person_id)
    if not isinstance(person_details, dict):
        return None
    return person_details.get("birthday")


def main():
    trending_show = get_most_trending_tv_show()
    if trending_show is None:
        print("No trending TV show data available.")
        return

    show_details = get_tv_show_details(trending_show)
    if show_details is None:
        print("Unable to fetch TV show details.")
        return

    lead_actor_name = determine_lead_actor(show_details)
    if not lead_actor_name:
        print("Unable to determine the lead actor from the available data.")
        return

    person_record = find_person_record(lead_actor_name)
    if person_record is None:
        print(f"Unable to find a person record for: {lead_actor_name}")
        return

    birthday = get_actor_birthday(person_record)
    if birthday:
        print(f"Lead actor: {lead_actor_name}")
        print(f"Birthday: {birthday}")
    else:
        print(f"Lead actor: {lead_actor_name}")
        print("Birthday: N/A")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

