from Get_trending_tv import Get_trending_tv
from Get_tv_images import Get_tv_images

import traceback

TRENDING_TIME_WINDOW = "day"
TMDB_IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original"


def fetch_trending_tv():
    try:
        return Get_trending_tv(TRENDING_TIME_WINDOW)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch trending TV shows: {exc}") from exc


def select_most_trending_show(trending_payload):
    results = trending_payload.get("results", [])
    if not results:
        return None
    return results[0]


def extract_show_id(show):
    if not isinstance(show, dict):
        return None
    return show.get("id")


def fetch_tv_images(series_id):
    try:
        return Get_tv_images(series_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch TV images for series_id={series_id}: {exc}") from exc


def select_best_poster(image_payload):
    posters = image_payload.get("posters", [])
    if posters:
        sorted_posters = sorted(
            posters,
            key=lambda item: (
                float(item.get("vote_average") or 0.0),
                int(item.get("vote_count") or 0),
                float(item.get("aspect_ratio") or 0.0),
                int(item.get("width") or 0),
                int(item.get("height") or 0),
            ),
            reverse=True,
        )
        return sorted_posters[0]

    backdrops = image_payload.get("backdrops", [])
    if backdrops:
        sorted_backdrops = sorted(
            backdrops,
            key=lambda item: (
                float(item.get("vote_average") or 0.0),
                int(item.get("vote_count") or 0),
                float(item.get("aspect_ratio") or 0.0),
                int(item.get("width") or 0),
                int(item.get("height") or 0),
            ),
            reverse=True,
        )
        return sorted_backdrops[0]

    logos = image_payload.get("logos", [])
    if logos:
        sorted_logos = sorted(
            logos,
            key=lambda item: (
                float(item.get("vote_average") or 0.0),
                int(item.get("vote_count") or 0),
                float(item.get("aspect_ratio") or 0.0),
                int(item.get("width") or 0),
                int(item.get("height") or 0),
            ),
            reverse=True,
        )
        return sorted_logos[0]

    return None


def build_image_url(file_path):
    if not file_path:
        return None
    return f"{TMDB_IMAGE_BASE_URL}{file_path}"


def format_poster_output(show, poster):
    show_name = (show or {}).get("name") or (show or {}).get("original_name") or "Unknown TV Show"
    poster_path = (poster or {}).get("file_path")
    poster_url = build_image_url(poster_path)

    lines = []
    lines.append(f"Today's most trending TV show: {show_name}")
    if poster_url:
        lines.append(f"Poster URL: {poster_url}")
    else:
        lines.append("Poster URL: unavailable")

    if show:
        show_id = show.get("id")
        if show_id is not None:
            lines.append(f"TMDB ID: {show_id}")

    return "\n".join(lines)


def main():
    trending_payload = fetch_trending_tv()
    trending_show = select_most_trending_show(trending_payload)

    if not trending_show:
        print("No trending TV show data available for today.")
        return

    series_id = extract_show_id(trending_show)
    if series_id is None:
        print("Trending TV show found, but no valid series ID was available.")
        return

    image_payload = fetch_tv_images(series_id)
    poster = select_best_poster(image_payload)

    output = format_poster_output(trending_show, poster)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

