from Search_person import Search_person
from Get_tv_details import Get_tv_details
from Get_tv_details import Get_tv_details

import traceback

# Module-level constants pinned from the user requirement / reasonable assumptions
TARGET_PERSON_NAME = "Jeremy Clarkson"
TV_SHOW_QUERY = "Jeremy Clarkson"
MAX_PERSON_SEARCH_RESULTS = 5


def safe_get(dct, path, default=None):
    current = dct
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


def select_best_matching_person(search_response, target_name):
    results = safe_get(search_response, ["results"], [])
    if not isinstance(results, list) or not results:
        return None

    target_lower = target_name.lower().strip()
    best_match = None

    for person in results[:MAX_PERSON_SEARCH_RESULTS]:
        name = str(person.get("name", ""))
        original_name = str(person.get("original_name", ""))
        known_for_department = str(person.get("known_for_department", ""))
        haystack = f"{name} {original_name} {known_for_department}".lower()

        if target_lower in haystack:
            best_match = person
            break

    if best_match is None:
        best_match = results[0]

    return best_match


def search_person_by_name(person_name):
    try:
        return Search_person(person_name)
    except Exception:
        return None


def get_person_record(person_name):
    search_response = search_person_by_name(person_name)
    if not search_response:
        return None
    return select_best_matching_person(search_response, person_name)


def select_most_popular_tv_show(person_record):
    known_for = person_record.get("known_for", []) if isinstance(person_record, dict) else []
    if not isinstance(known_for, list) or not known_for:
        return None

    tv_candidates = []
    for item in known_for:
        if not isinstance(item, dict):
            continue
        media_type = str(item.get("media_type", "")).lower()
        if media_type == "tv":
            tv_candidates.append(item)

    if not tv_candidates:
        return None

    return max(tv_candidates, key=lambda x: float(x.get("popularity", 0) or 0))


def get_tv_details(series_id):
    try:
        return Get_tv_details(series_id)
    except Exception:
        return None


def extract_coworkers_from_tv_details(tv_details, target_person_name):
    coworkers = []

    if not isinstance(tv_details, dict):
        return coworkers

    target_lower = target_person_name.lower().strip()

    created_by = tv_details.get("created_by", [])
    if isinstance(created_by, list):
        for creator in created_by:
            if not isinstance(creator, dict):
                continue
            name = str(creator.get("name", "")).strip()
            if name and name.lower() != target_lower:
                coworkers.append(name)

    production_companies = tv_details.get("production_companies", [])
    if isinstance(production_companies, list):
        for company in production_companies:
            if not isinstance(company, dict):
                continue
            name = str(company.get("name", "")).strip()
            if name:
                coworkers.append(name)

    networks = tv_details.get("networks", [])
    if isinstance(networks, list):
        for network in networks:
            if not isinstance(network, dict):
                continue
            name = str(network.get("name", "")).strip()
            if name:
                coworkers.append(name)

    unique_coworkers = []
    seen = set()
    for name in coworkers:
        key = name.lower()
        if key not in seen:
            seen.add(key)
            unique_coworkers.append(name)

    return unique_coworkers


def find_people_who_worked_with_target():
    person_record = get_person_record(TARGET_PERSON_NAME)
    if not person_record:
        return []

    most_popular_tv_show = select_most_popular_tv_show(person_record)
    if not most_popular_tv_show:
        return []

    series_id = most_popular_tv_show.get("id")
    if series_id is None:
        return []

    tv_details = get_tv_details(series_id)
    if not tv_details:
        return []

    coworkers = extract_coworkers_from_tv_details(tv_details, TARGET_PERSON_NAME)
    return coworkers


def print_results(coworkers):
    if coworkers:
        print(f"People who have worked with {TARGET_PERSON_NAME} in his most popular TV show:")
        for name in coworkers:
            print(f"- {name}")
    else:
        print(f"No coworkers found for {TARGET_PERSON_NAME} in his most popular TV show.")


def main():
    coworkers = find_people_who_worked_with_target()
    print_results(coworkers)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
