from Search_tv import Search_tv
from Get_tv_season_details import Get_tv_season_details
from Get_tv_episode_credits import Get_tv_episode_credits
from Get_person_details import Get_person_details

import traceback

SHOW_QUERY = "Black Mirror"
SEASON_NUMBER = 2
EPISODE_NUMBER = 1


def search_tv_show(query):
    if query is None:
        raise ValueError("query is required")
    result = Search_tv(query)
    return result


def select_best_show(search_response):
    results = search_response.get("results", []) if isinstance(search_response, dict) else []
    if not results:
        return None

    target = SHOW_QUERY.lower()
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if target in name or target in original_name:
            return item

    return results[0]


def get_season_details(series_id, season_number):
    if series_id is None:
        raise ValueError("series_id is required")
    if season_number is None:
        raise ValueError("season_number is required")
    return Get_tv_season_details(series_id, season_number)


def get_first_episode_from_season(season_details):
    episodes = season_details.get("episodes", []) if isinstance(season_details, dict) else []
    if not episodes:
        return None
    return episodes[0]


def get_episode_credits(series_id, season_number, episode_number):
    if series_id is None:
        raise ValueError("series_id is required")
    if season_number is None:
        raise ValueError("season_number is required")
    if episode_number is None:
        raise ValueError("episode_number is required")
    return Get_tv_episode_credits(series_id, season_number, episode_number)


def choose_lead_actor(credits_response):
    cast = credits_response.get("cast", []) if isinstance(credits_response, dict) else []
    if not cast:
        return None
    return cast[0]


def get_person_details(person_id):
    if person_id is None:
        raise ValueError("person_id is required")
    return Get_person_details(person_id)


def build_appearance_summary(person_details):
    if not isinstance(person_details, dict):
        return "No actor details available."

    name = person_details.get("name", "Unknown actor")
    known_for_department = person_details.get("known_for_department", "Unknown department")
    profile_path = person_details.get("profile_path")
    birthday = person_details.get("birthday")
    place_of_birth = person_details.get("place_of_birth")
    biography = person_details.get("biography", "")

    parts = [f"Lead actor: {name}"]
    if known_for_department:
        parts.append(f"Known for: {known_for_department}")
    if birthday:
        parts.append(f"Born: {birthday}")
    if place_of_birth:
        parts.append(f"Birthplace: {place_of_birth}")
    if profile_path:
        parts.append(f"Profile image path: {profile_path}")
    if biography:
        parts.append(f"Biography: {biography}")

    return "\n".join(parts)


def find_lead_actor_appearance():
    search_response = search_tv_show(SHOW_QUERY)
    selected_show = select_best_show(search_response)
    if not selected_show:
        return "No matching TV show found."

    series_id = selected_show.get("id")
    season_details = get_season_details(series_id, SEASON_NUMBER)
    first_episode = get_first_episode_from_season(season_details)

    if not first_episode:
        return "No episodes found for the selected season."

    episode_number = first_episode.get("episode_number", EPISODE_NUMBER)
    credits = get_episode_credits(series_id, SEASON_NUMBER, episode_number)
    lead_actor = choose_lead_actor(credits)

    if not lead_actor:
        return "No cast information found for the selected episode."

    actor_id = lead_actor.get("id")
    person_details = get_person_details(actor_id)
    return build_appearance_summary(person_details)


def main():
    appearance = find_lead_actor_appearance()
    print(appearance)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

