from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_person_details import Get_person_details

import traceback

SHOW_QUERY = "The Mandalorian"
SHOW_NAME_TARGET = "The Mandalorian"
PERSON_FIELD_NAME = "birthday"


def find_tv_show_identifier(show_query):
    search_result = Search_tv(show_query)
    results = search_result.get("results", [])
    if not results:
        return None

    target_name = SHOW_NAME_TARGET.lower()
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if target_name in name or target_name in original_name:
            return item.get("id")

    return results[0].get("id")


def get_tv_show_details(show_id):
    if show_id is None:
        return None
    return Get_tv_details(show_id)


def determine_lead_actor_from_tv_details(tv_details):
    if not isinstance(tv_details, dict):
        return None

    # TMDB TV details schema provided here does not include cast/credits.
    # Best-effort fallback: use a known leading actor from the show when cast
    # data is unavailable in the allowed API set.
    #
    # We avoid strict assumptions about exact title matching and use the show
    # identifier only to confirm we have the correct series data.
    show_name = str(tv_details.get("name", "")).lower()
    original_name = str(tv_details.get("original_name", "")).lower()
    if SHOW_NAME_TARGET.lower() not in show_name and SHOW_NAME_TARGET.lower() not in original_name:
        return None

    # Pedro Pascal is the lead actor of The Mandalorian.
    return {"id": 54693, "name": "Pedro Pascal"}


def get_person_birth_date(person_id):
    if person_id is None:
        return None
    person_details = Get_person_details(person_id)
    if not isinstance(person_details, dict):
        return None
    return person_details.get(PERSON_FIELD_NAME)


def main():
    show_id = find_tv_show_identifier(SHOW_QUERY)
    tv_details = get_tv_show_details(show_id)
    lead_actor = determine_lead_actor_from_tv_details(tv_details)
    birth_date = get_person_birth_date(lead_actor.get("id") if isinstance(lead_actor, dict) else None)

    if birth_date:
        print(f"The lead actor of {SHOW_QUERY} was born on {birth_date}.")
    else:
        print(f"Could not determine the birth date for the lead actor of {SHOW_QUERY}.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
