from Get_trending_tv import Get_trending_tv
from Get_tv_details import Get_tv_details
from Get_person_images import Get_person_images

import traceback

TIME_WINDOW = "week"
IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original"


def safe_get(obj, *path, default=None):
    current = obj
    for key in path:
        if not isinstance(current, dict):
            return default
        current = current.get(key, default)
        if current is default:
            return default
    return current


def choose_top_trending_tv_show(trending_payload):
    results = safe_get(trending_payload, "results", default=[])
    if not isinstance(results, list) or not results:
        return None
    return max(results, key=lambda item: float(item.get("popularity", 0) or 0))


def get_most_popular_weekly_tv_show():
    trending_payload = Get_trending_tv(TIME_WINDOW)
    return choose_top_trending_tv_show(trending_payload)


def get_lead_actor_for_tv_show(tv_show):
    series_id = tv_show.get("id")
    tv_details = Get_tv_details(series_id)

    created_by = tv_details.get("created_by", [])
    if isinstance(created_by, list) and created_by:
        candidate = created_by[0]
        person_id = candidate.get("id")
        if person_id is not None:
            return {
                "id": person_id,
                "name": candidate.get("name", "Unknown"),
                "profile_path": candidate.get("profile_path"),
            }

    return None


def choose_best_image(person_images):
    profiles = safe_get(person_images, "profiles", default=[])
    if not isinstance(profiles, list) or not profiles:
        return None

    def score(profile):
        vote_average = float(profile.get("vote_average", 0) or 0)
        vote_count = int(profile.get("vote_count", 0) or 0)
        width = int(profile.get("width", 0) or 0)
        height = int(profile.get("height", 0) or 0)
        return (vote_average, vote_count, width * height)

    return max(profiles, key=score)


def get_photo_for_person(person):
    person_id = person.get("id")
    person_images = Get_person_images(person_id)
    return choose_best_image(person_images)


def format_photo_output(person, photo):
    if not photo:
        return f"No photo found for {person.get('name', 'the lead actor')}."

    file_path = photo.get("file_path")
    image_url = f"{IMAGE_BASE_URL}{file_path}" if file_path else "No image path available"
    actor_name = person.get("name", "Lead actor")
    return f"Lead actor: {actor_name}\nPhoto URL: {image_url}"


def main():
    top_show = get_most_popular_weekly_tv_show()
    if not top_show:
        return "No trending TV shows found this week."

    lead_actor = get_lead_actor_for_tv_show(top_show)
    if not lead_actor:
        return f"No lead actor information found for the weekly top TV show: {top_show.get('name', 'Unknown')}."

    photo = get_photo_for_person(lead_actor)
    return format_photo_output(lead_actor, photo)


if __name__ == "__main__":
    try:
        output = main()
        print(output)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

