from Search_person import Search_person
from Get_person_tv_credits import Get_person_tv_credits
from Get_tv_series_reviews import Get_tv_series_reviews

import traceback

CATE_BLANCHETT_QUERY = "Cate Blanchett"
MAX_REVIEWS_TO_PRINT = 3
TV_MEDIA_TYPE = "tv"


def find_person_by_name(name_query):
    try:
        search_data = Search_person(name_query)
        results = search_data.get("results", []) if isinstance(search_data, dict) else []
        if not results:
            return None

        query_lower = str(name_query).lower()
        best_match = None
        best_score = -1

        for person in results:
            name = str(person.get("name", ""))
            original_name = str(person.get("original_name", ""))
            known_for_department = str(person.get("known_for_department", ""))
            score = 0

            if query_lower in name.lower():
                score += 5
            if query_lower in original_name.lower():
                score += 3
            if "act" in known_for_department.lower():
                score += 1

            known_for = person.get("known_for", [])
            for item in known_for if isinstance(known_for, list) else []:
                title = str(item.get("title", ""))
                media_type = str(item.get("media_type", ""))
                if media_type.lower() == TV_MEDIA_TYPE and title:
                    score += 1

            popularity = person.get("popularity", 0) or 0
            try:
                score += min(float(popularity) / 100.0, 2)
            except Exception:
                pass

            if score > best_score:
                best_score = score
                best_match = person

        if best_match is None:
            return None

        return best_match.get("id")
    except Exception:
        raise


def extract_recent_tv_show(tv_credit_item):
    first_air_date = str(tv_credit_item.get("first_air_date", "") or "")
    name = str(tv_credit_item.get("name", "") or "")
    show_id = tv_credit_item.get("id")

    return {
        "id": show_id,
        "name": name,
        "first_air_date": first_air_date,
        "vote_average": tv_credit_item.get("vote_average", 0),
        "vote_count": tv_credit_item.get("vote_count", 0),
        "character": tv_credit_item.get("character", ""),
        "episode_count": tv_credit_item.get("episode_count", 0),
    }


def get_latest_tv_show_for_person(person_id):
    try:
        tv_credits = Get_person_tv_credits(person_id)
        cast_credits = tv_credits.get("cast", []) if isinstance(tv_credits, dict) else []
        crew_credits = tv_credits.get("crew", []) if isinstance(tv_credits, dict) else []

        combined = []
        if isinstance(cast_credits, list):
            combined.extend(cast_credits)
        if isinstance(crew_credits, list):
            combined.extend(crew_credits)

        if not combined:
            return None

        def sort_key(item):
            date = str(item.get("first_air_date", "") or "")
            popularity = item.get("popularity", 0) or 0
            vote_count = item.get("vote_count", 0) or 0
            return (date, float(popularity), int(vote_count))

        latest_item = max(combined, key=sort_key)
        latest_show = extract_recent_tv_show(latest_item)
        return latest_show
    except Exception:
        raise


def fetch_tv_show_reviews(show_id):
    try:
        reviews_data = Get_tv_series_reviews(show_id)
        results = reviews_data.get("results", []) if isinstance(reviews_data, dict) else []
        return results
    except Exception:
        raise


def select_some_reviews(reviews, limit=MAX_REVIEWS_TO_PRINT):
    if not isinstance(reviews, list) or not reviews:
        return []

    selected = []
    for review in reviews[:limit]:
        author = review.get("author", "Unknown author")
        content = review.get("content", "")
        created_at = review.get("created_at", "")
        rating = None
        author_details = review.get("author_details", {})
        if isinstance(author_details, dict):
            rating = author_details.get("rating", None)

        selected.append(
            {
                "author": author,
                "created_at": created_at,
                "rating": rating,
                "content": content,
            }
        )
    return selected


def format_review(review):
    author = review.get("author", "Unknown author")
    created_at = review.get("created_at", "Unknown date")
    rating = review.get("rating", None)
    content = str(review.get("content", "")).strip()

    lines = [
        f"Author: {author}",
        f"Date: {created_at}",
        f"Rating: {rating if rating is not None else 'N/A'}",
        f"Review: {content}",
    ]
    return "\n".join(lines)


def print_reviews(person_name, show_info, reviews):
    show_name = show_info.get("name", "Unknown TV show") if isinstance(show_info, dict) else "Unknown TV show"
    first_air_date = show_info.get("first_air_date", "Unknown date") if isinstance(show_info, dict) else "Unknown date"

    print(f"Latest TV show for {person_name}: {show_name} ({first_air_date})")
    print("-" * 60)

    if not reviews:
        print("No reviews were found for this TV show.")
        return

    for idx, review in enumerate(reviews, start=1):
        print(f"Review {idx}")
        print(format_review(review))
        if idx != len(reviews):
            print("-" * 60)


def main():
    person_id = find_person_by_name(CATE_BLANCHETT_QUERY)
    if person_id is None:
        print(f"No person found for: {CATE_BLANCHETT_QUERY}")
        return

    latest_show = get_latest_tv_show_for_person(person_id)
    if latest_show is None or latest_show.get("id") is None:
        print(f"No TV credits found for: {CATE_BLANCHETT_QUERY}")
        return

    reviews = fetch_tv_show_reviews(latest_show["id"])
    some_reviews = select_some_reviews(reviews, MAX_REVIEWS_TO_PRINT)
    print_reviews(CATE_BLANCHETT_QUERY, latest_show, some_reviews)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

