from Search_person import Search_person
from Get_person_tv_credits import Get_person_tv_credits
from Get_tv_details import Get_tv_details

import traceback

# Module-level pinned constants
PERSON_NAME_QUERY = "David Schwimmer"
TV_CREDITS_KEY_CAST = "cast"
TV_CREDITS_KEY_ID = "id"
TV_DETAILS_KEY_NAME = "name"
TV_DETAILS_KEY_POPULARITY = "popularity"
TV_DETAILS_KEY_OVERVIEW = "overview"
TV_DETAILS_KEY_FIRST_AIR_DATE = "first_air_date"

# The required API functions are assumed to be available in the execution environment:
# Search_person, Get_person_tv_credits, Get_tv_details


def search_person_by_name(name_query):
    if name_query is None:
        raise ValueError("name_query is required.")
    return Search_person(name_query)


def select_matching_person(search_results, requested_name):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    requested_lower = (requested_name or "").strip().lower()

    def score_person(person):
        name = str(person.get("name", "")).strip().lower()
        original_name = str(person.get("original_name", "")).strip().lower()
        score = 0
        if requested_lower and requested_lower in name:
            score += 3
        if requested_lower and requested_lower in original_name:
            score += 3
        if name == requested_lower:
            score += 5
        if original_name == requested_lower:
            score += 5
        return score, float(person.get("popularity", 0) or 0)

    ranked = sorted(results, key=score_person, reverse=True)
    return ranked[0].get("id") if ranked else None


def get_person_tv_credits(person_id):
    if person_id is None:
        raise ValueError("person_id is required.")
    return Get_person_tv_credits(person_id)


def extract_tv_ids_from_credits(tv_credit_list):
    if not isinstance(tv_credit_list, dict):
        return []
    cast_list = tv_credit_list.get(TV_CREDITS_KEY_CAST, [])
    tv_ids = []
    for credit in cast_list:
        if isinstance(credit, dict) and TV_CREDITS_KEY_ID in credit:
            tv_ids.append(credit[TV_CREDITS_KEY_ID])
    return tv_ids


def get_tv_details_for_credits(tv_ids):
    details = []
    for series_id in tv_ids:
        try:
            tv_detail = Get_tv_details(series_id)
            if isinstance(tv_detail, dict):
                details.append(tv_detail)
        except Exception:
            continue
    return details


def find_most_popular_tv_show(tv_detail_list):
    if not tv_detail_list:
        return None
    ranked = sorted(
        tv_detail_list,
        key=lambda item: float(item.get(TV_DETAILS_KEY_POPULARITY, 0) or 0),
        reverse=True,
    )
    return ranked[0] if ranked else None


def format_tv_show_output(tv_show, person_name):
    if not tv_show:
        return f"No TV show data found for {person_name}."

    name = tv_show.get(TV_DETAILS_KEY_NAME, "Unknown")
    popularity = tv_show.get(TV_DETAILS_KEY_POPULARITY, "Unknown")
    first_air_date = tv_show.get(TV_DETAILS_KEY_FIRST_AIR_DATE, "Unknown")
    overview = tv_show.get(TV_DETAILS_KEY_OVERVIEW, "")

    lines = [
        f"Most popular TV show for {person_name}:",
        f"Title: {name}",
        f"Popularity: {popularity}",
        f"First air date: {first_air_date}",
    ]
    if overview:
        lines.append(f"Overview: {overview}")
    return "\n".join(lines)


def main():
    search_results = search_person_by_name(PERSON_NAME_QUERY)
    person_id = select_matching_person(search_results, PERSON_NAME_QUERY)

    if person_id is None:
        print(f"No matching person found for {PERSON_NAME_QUERY}.")
        return

    tv_credits = get_person_tv_credits(person_id)
    tv_ids = extract_tv_ids_from_credits(tv_credits)
    tv_details_list = get_tv_details_for_credits(tv_ids)
    most_popular_tv_show = find_most_popular_tv_show(tv_details_list)
    output = format_tv_show_output(most_popular_tv_show, PERSON_NAME_QUERY)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

