from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_details import Get_tv_season_details
from Get_tv_episode_credits import Get_tv_episode_credits

import traceback

BLACK_MIRROR_QUERY = "Black Mirror"
TARGET_SEASON_NUMBER = 2
TARGET_EPISODE_POSITION = 3
DIRECTOR_JOB_KEYWORDS = ("director",)


def find_show_id(show_name):
    search_result = Search_tv(query=show_name)
    results = search_result.get("results", [])
    if not results:
        return None

    normalized_target = show_name.strip().lower()
    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if normalized_target in name or normalized_target in original_name:
            return item.get("id")

    return results[0].get("id")


def get_show_details(show_id):
    if show_id is None:
        return None
    return Get_tv_details(series_id=show_id)


def get_second_season(show_id):
    if show_id is None:
        return None
    return Get_tv_season_details(series_id=show_id, season_number=TARGET_SEASON_NUMBER)


def get_third_episode_from_season(season_details):
    episodes = season_details.get("episodes", []) if season_details else []
    if len(episodes) < TARGET_EPISODE_POSITION:
        return None
    return episodes[TARGET_EPISODE_POSITION - 1]


def get_episode_credits(show_id, season_number, episode_number):
    if show_id is None or episode_number is None:
        return None
    return Get_tv_episode_credits(
        series_id=show_id,
        season_number=season_number,
        episode_number=episode_number,
    )


def determine_director(episode_credits):
    if not episode_credits:
        return None

    crew = episode_credits.get("crew", [])
    for person in crew:
        department = str(person.get("department", "")).strip().lower()
        job = str(person.get("job", "")).strip().lower()
        if any(keyword in department for keyword in DIRECTOR_JOB_KEYWORDS) or any(
            keyword in job for keyword in DIRECTOR_JOB_KEYWORDS
        ):
            return person.get("name")

    return None


def main():
    show_id = find_show_id(BLACK_MIRROR_QUERY)
    _show_details = get_show_details(show_id)
    season_details = get_second_season(show_id)
    third_episode = get_third_episode_from_season(season_details)
    episode_number = third_episode.get("episode_number") if third_episode else None
    episode_credits = get_episode_credits(show_id, TARGET_SEASON_NUMBER, episode_number)
    director = determine_director(episode_credits)

    if director:
        print(director)
    else:
        print("Director not found.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
