from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_person_movie_credits import Get_person_movie_credits

import traceback

CHRISTOPHER_NOLAN_QUERY = "Christopher Nolan"
MAX_NOTABLE_MOVIES = 5


def safe_get(dct, path, default=None):
    current = dct
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current if current is not None else default


def choose_best_matching_person(search_response):
    results = safe_get(search_response, ["results"], [])
    if not results:
        return None

    query_lower = CHRISTOPHER_NOLAN_QUERY.lower()
    best = None
    best_score = -1

    for person in results:
        name = str(person.get("name", "")).lower()
        original_name = str(person.get("original_name", "")).lower()
        known_for_department = str(person.get("known_for_department", "")).lower()

        score = 0
        if query_lower in name:
            score += 10
        if query_lower in original_name:
            score += 10
        if "direct" in known_for_department:
            score += 5
        score += int(person.get("popularity", 0) or 0)

        if score > best_score:
            best_score = score
            best = person

    return best


def extract_person_id(person):
    if not person:
        return None
    return person.get("id")


def search_christopher_nolan():
    return Search_person(CHRISTOPHER_NOLAN_QUERY)


def fetch_nolan_movie_credits(person_id):
    if person_id is None:
        return {"cast": [], "crew": [], "id": None}
    return Get_person_movie_credits(person_id)


def identify_notable_movies_from_credits(credits):
    crew = safe_get(credits, ["crew"], [])
    cast = safe_get(credits, ["cast"], [])

    movies = {}

    for item in crew:
        if not isinstance(item, dict):
            continue
        title = item.get("title") or item.get("original_title")
        if not title:
            continue
        movies[title] = {
            "title": title,
            "release_date": item.get("release_date", ""),
            "vote_average": item.get("vote_average", 0),
            "vote_count": item.get("vote_count", 0),
            "popularity": item.get("popularity", 0),
            "job": item.get("job", ""),
            "department": item.get("department", ""),
        }

    for item in cast:
        if not isinstance(item, dict):
            continue
        title = item.get("title") or item.get("original_title")
        if not title:
            continue
        if title not in movies:
            movies[title] = {
                "title": title,
                "release_date": item.get("release_date", ""),
                "vote_average": item.get("vote_average", 0),
                "vote_count": item.get("vote_count", 0),
                "popularity": item.get("popularity", 0),
                "job": "cast",
                "department": "cast",
            }

    return list(movies.values())


def choose_representative_movies(known_for_movies):
    sorted_movies = sorted(
        known_for_movies,
        key=lambda m: (
            -(m.get("vote_average") or 0),
            -(m.get("vote_count") or 0),
            -(m.get("popularity") or 0),
            str(m.get("release_date", "")),
            str(m.get("title", "")),
        ),
    )
    return sorted_movies[:MAX_NOTABLE_MOVIES]


def format_notable_movies(notable_movies):
    if not notable_movies:
        return "No movies found for Christopher Nolan."

    lines = ["Some movies Christopher Nolan is known for:"]
    for idx, movie in enumerate(notable_movies, 1):
        title = movie.get("title", "Unknown Title")
        release_date = movie.get("release_date") or "Unknown release date"
        vote_average = movie.get("vote_average")
        vote_count = movie.get("vote_count")

        rating_text = f"{vote_average:.1f}" if isinstance(vote_average, (int, float)) else "N/A"
        count_text = str(vote_count) if isinstance(vote_count, int) else "N/A"
        lines.append(f"{idx}. {title} ({release_date}) - rating {rating_text}, votes {count_text}")
    return "\n".join(lines)


def main():
    search_response = search_christopher_nolan()
    selected_person = choose_best_matching_person(search_response)
    person_id = extract_person_id(selected_person)
    credits = fetch_nolan_movie_credits(person_id)
    notable_movies = identify_notable_movies_from_credits(credits)
    selected_movies = choose_representative_movies(notable_movies)
    print(format_notable_movies(selected_movies))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

