from Search_movie import Search_movie
from Get_movie_details import Get_movie_details
from Get_movie_details import Get_movie_details

import traceback

TITLE_ONE = "Avatar"
TITLE_TWO = "Avatar: The Way of Water"
RATING_KEY_PATH = ("vote_average",)


def search_movie_by_title(title):
    try:
        return Search_movie(title)
    except Exception:
        raise


def select_matching_movie(search_results, target_title):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    target_lower = str(target_title).lower()

    for movie in results:
        title = str(movie.get("title", "")).lower()
        original_title = str(movie.get("original_title", "")).lower()
        if target_lower in title or target_lower in original_title:
            return movie

    return results[0] if results else None


def get_movie_rating(movie_id):
    details = Get_movie_details(movie_id)
    return details.get("vote_average")


def compare_ratings(title_one, title_two):
    search_results_one = search_movie_by_title(title_one)
    movie_one = select_matching_movie(search_results_one, title_one)
    if not movie_one:
        return {"winner": None, "reason": f"No search result found for {title_one}"}

    rating_one = get_movie_rating(movie_one["id"])

    search_results_two = search_movie_by_title(title_two)
    movie_two = select_matching_movie(search_results_two, title_two)
    if not movie_two:
        return {"winner": None, "reason": f"No search result found for {title_two}"}

    rating_two = get_movie_rating(movie_two["id"])

    if rating_one is None and rating_two is None:
        return {"winner": "equal", "rating_one": rating_one, "rating_two": rating_two}
    if rating_two is None:
        return {"winner": title_one, "rating_one": rating_one, "rating_two": rating_two}
    if rating_one is None:
        return {"winner": title_two, "rating_one": rating_one, "rating_two": rating_two}

    if rating_one > rating_two:
        return {"winner": title_one, "rating_one": rating_one, "rating_two": rating_two}
    if rating_two > rating_one:
        return {"winner": title_two, "rating_one": rating_one, "rating_two": rating_two}

    return {"winner": "equal", "rating_one": rating_one, "rating_two": rating_two}


def format_comparison_result(result, title_one, title_two):
    if result.get("winner") == "equal":
        return (
            f"{title_one} and {title_two} have the same rating.\n"
            f"{title_one}: {result.get('rating_one')}\n"
            f"{title_two}: {result.get('rating_two')}"
        )
    if result.get("winner") == title_one:
        return (
            f"{title_one} has a higher rating than {title_two}.\n"
            f"{title_one}: {result.get('rating_one')}\n"
            f"{title_two}: {result.get('rating_two')}"
        )
    if result.get("winner") == title_two:
        return (
            f"{title_two} has a higher rating than {title_one}.\n"
            f"{title_one}: {result.get('rating_one')}\n"
            f"{title_two}: {result.get('rating_two')}"
        )
    return result.get("reason", "Unable to determine which movie has a higher rating.")


def main():
    result = compare_ratings(TITLE_ONE, TITLE_TWO)
    print(format_comparison_result(result, TITLE_ONE, TITLE_TWO))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

