from Search_movie import Search_movie
from Get_movie_details import Get_movie_details

import traceback

MOVIE_TITLE_QUERY = "Lord of the Ring"
TITLE_MATCH_TERMS = ["lord of the ring", "lord of the rings"]
GENRE_KEY = "genres"
TITLE_KEY = "title"
ID_KEY = "id"
RESULTS_KEY = "results"


def search_for_movie_title(movie_title):
    try:
        return Search_movie(movie_title)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for movie title '{movie_title}': {exc}") from exc


def select_matching_movie(search_results, requested_title):
    try:
        results = search_results.get(RESULTS_KEY, [])
        if not results:
            return None

        requested_lower = requested_title.lower()
        for movie in results:
            title = movie.get(TITLE_KEY, "")
            title_lower = title.lower()
            if any(term in title_lower for term in TITLE_MATCH_TERMS) or requested_lower in title_lower:
                return movie.get(ID_KEY)

        first_movie = results[0]
        return first_movie.get(ID_KEY)
    except Exception as exc:
        raise RuntimeError(f"Failed to select matching movie: {exc}") from exc


def retrieve_movie_details(movie_id):
    try:
        if movie_id is None:
            return None
        return Get_movie_details(movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve movie details for id '{movie_id}': {exc}") from exc


def extract_genre_information(movie_details):
    try:
        if not movie_details:
            return []
        genres = movie_details.get(GENRE_KEY, [])
        genre_names = []
        for genre in genres:
            name = genre.get("name")
            if name:
                genre_names.append(name)
        return genre_names
    except Exception as exc:
        raise RuntimeError(f"Failed to extract genre information: {exc}") from exc


def format_genre_output(movie_title, genres):
    if genres:
        return f"The genre(s) of '{movie_title}' are: {', '.join(genres)}."
    return f"No genre information found for '{movie_title}'."


def main():
    search_results = search_for_movie_title(MOVIE_TITLE_QUERY)
    movie_id = select_matching_movie(search_results, MOVIE_TITLE_QUERY)
    movie_details = retrieve_movie_details(movie_id)
    genre_info = extract_genre_information(movie_details)
    print(format_genre_output(MOVIE_TITLE_QUERY, genre_info))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

