from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_details import Get_tv_season_details

import traceback

SHOW_SEARCH_QUERY = "Big Bang Theory"
TARGET_SEASON_NUMBER = 2
POSTER_BASE_URL = "https://image.tmdb.org/t/p/original"


def search_show(query):
    if query is None:
        raise ValueError("query is required")
    return Search_tv(query)


def get_show_details(show_id):
    if show_id is None:
        raise ValueError("show_id is required")
    return Get_tv_details(show_id)


def get_season_details(show_id, season_number):
    if show_id is None:
        raise ValueError("show_id is required")
    if season_number is None:
        raise ValueError("season_number is required")
    return Get_tv_season_details(show_id, season_number)


def pick_best_show(search_results):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    query_lower = SHOW_SEARCH_QUERY.lower()
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if query_lower in name or query_lower in original_name:
            return item

    return results[0]


def extract_season_poster_path(season_info):
    if not isinstance(season_info, dict):
        return None
    return season_info.get("poster_path")


def format_poster_url(poster_path):
    if not poster_path:
        return None
    if str(poster_path).startswith("http://") or str(poster_path).startswith("https://"):
        return poster_path
    return f"{POSTER_BASE_URL}{poster_path}"


def build_output_message(show_name, season_number, poster_url, season_info):
    season_name = None
    if isinstance(season_info, dict):
        season_name = season_info.get("name")

    title = show_name or "Unknown show"
    if season_name:
        header = f"Poster for {title} - {season_name}"
    else:
        header = f"Poster for {title} - Season {season_number}"

    if poster_url:
        return f"{header}\n{poster_url}"
    return f"{header}\nNo poster found."


def main():
    search_results = search_show(SHOW_SEARCH_QUERY)
    show_entry = pick_best_show(search_results)

    if not show_entry:
        print("No matching show found.")
        return

    show_id = show_entry.get("id")
    show_details = get_show_details(show_id) if show_id is not None else {}
    season_info = get_season_details(show_id, TARGET_SEASON_NUMBER) if show_id is not None else {}

    poster_path = extract_season_poster_path(season_info)
    poster_url = format_poster_url(poster_path)

    show_name = None
    if isinstance(show_details, dict):
        show_name = show_details.get("name") or show_entry.get("name")

    message = build_output_message(show_name, TARGET_SEASON_NUMBER, poster_url, season_info)
    print(message)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

