from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_details import Get_tv_season_details

import traceback

MANDALORIAN_QUERY = "Mandalorian"
TARGET_SEASON_NUMBER = 2
TARGET_EPISODE_INDEX = 3  # 1-based index for the third episode


def search_show(query):
    if not query:
        raise ValueError("query is required")
    return Search_tv(query)


def get_show_details(show_id):
    if show_id is None:
        raise ValueError("show_id is required")
    return Get_tv_details(show_id)


def get_season_details(show_id, season_number):
    if show_id is None:
        raise ValueError("show_id is required")
    if season_number is None:
        raise ValueError("season_number is required")
    return Get_tv_season_details(show_id, season_number)


def select_best_show(search_results, preferred_name_fragment):
    results = []
    if isinstance(search_results, dict):
        results = search_results.get("results", []) or []

    if not results:
        return None

    fragment = (preferred_name_fragment or "").lower()
    for item in results:
        name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if fragment in name or fragment in original_name:
            return item

    return results[0]


def find_season_entry(show_details, target_season_number):
    seasons = []
    if isinstance(show_details, dict):
        seasons = show_details.get("seasons", []) or []

    if not seasons:
        return None

    for season in seasons:
        season_number = season.get("season_number")
        if season_number is not None and int(season_number) == int(target_season_number):
            return season

    return None


def get_nth_episode_title(season_details, n):
    episodes = []
    if isinstance(season_details, dict):
        episodes = season_details.get("episodes", []) or []

    if len(episodes) < n:
        return None

    episode = episodes[n - 1]
    return episode.get("name")


def resolve_third_episode_of_second_season():
    search_results = search_show(MANDALORIAN_QUERY)
    show_entry = select_best_show(search_results, "Mandalorian")

    if not show_entry:
        return None

    show_id = show_entry.get("id")
    show_details = get_show_details(show_id)
    season_entry = find_season_entry(show_details, TARGET_SEASON_NUMBER)

    season_number = TARGET_SEASON_NUMBER
    if season_entry and season_entry.get("season_number") is not None:
        season_number = season_entry.get("season_number")

    season_details = get_season_details(show_id, season_number)
    return get_nth_episode_title(season_details, TARGET_EPISODE_INDEX)


def main():
    title = resolve_third_episode_of_second_season()
    if title:
        print(title)
    else:
        print("Unable to determine the episode title.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

