from Search_movie import Search_movie
from Get_movie_credits import Get_movie_credits
from Search_person import Search_person

import traceback

# =========================
# Module-level constants
# =========================
MOVIE_TITLE = "The Shawshank Redemption"
FALLBACK_MOVIE_TITLE = "Shawshank Redemption"
PERSON_QUERY_NORMALIZATION_MAP = {
    "lead actor": "lead actor",
    "primary cast": "primary cast",
}
MAX_CANDIDATE_RESULTS = 10


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def safe_get(dct, key, default=None):
    if isinstance(dct, dict):
        return dct.get(key, default)
    return default


def search_movie_candidates(movie_title):
    try:
        return Search_movie(query=movie_title)
    except Exception as exc:
        raise RuntimeError(f"Movie search failed for '{movie_title}': {exc}") from exc


def select_best_matching_movie_identifier(search_results, movie_title):
    results = safe_get(search_results, "results", []) or []
    if not isinstance(results, list) or not results:
        return None

    target = normalize_text(movie_title)
    fallback = normalize_text(FALLBACK_MOVIE_TITLE)

    for item in results[:MAX_CANDIDATE_RESULTS]:
        title = normalize_text(safe_get(item, "title", ""))
        original_title = normalize_text(safe_get(item, "original_title", ""))
        if target and (target in title or target in original_title):
            return safe_get(item, "id")
        if fallback and (fallback in title or fallback in original_title):
            return safe_get(item, "id")

    first = results[0]
    return safe_get(first, "id")


def find_movie_id(movie_title):
    search_results = search_movie_candidates(movie_title)
    return select_best_matching_movie_identifier(search_results, movie_title)


def get_movie_credits_by_id(movie_id):
    if movie_id is None:
        return None
    try:
        return Get_movie_credits(movie_id=movie_id)
    except Exception as exc:
        raise RuntimeError(f"Fetching credits failed for movie_id={movie_id}: {exc}") from exc


def select_primary_cast_member_name(credits):
    cast = safe_get(credits, "cast", []) or []
    if not isinstance(cast, list) or not cast:
        return None

    lead = cast[0]
    name = safe_get(lead, "name")
    if name:
        return name

    for member in cast[:MAX_CANDIDATE_RESULTS]:
        candidate_name = safe_get(member, "name")
        if candidate_name:
            return candidate_name
    return None


def get_lead_actor_name(movie_id):
    credits = get_movie_credits_by_id(movie_id)
    if not credits:
        return None
    return select_primary_cast_member_name(credits)


def search_person_candidates(person_name):
    if not person_name:
        return None
    try:
        return Search_person(query=person_name)
    except Exception:
        return None


def select_best_matching_person_identifier(person_search_results, person_name):
    results = safe_get(person_search_results, "results", []) or []
    if not isinstance(results, list) or not results:
        return None

    target = normalize_text(person_name)
    for item in results[:MAX_CANDIDATE_RESULTS]:
        name = normalize_text(safe_get(item, "name", ""))
        original_name = normalize_text(safe_get(item, "original_name", ""))
        if target and (target in name or target in original_name or name in target or original_name in target):
            return safe_get(item, "id")

    first = results[0]
    return safe_get(first, "id")


def get_person_birthday_via_available_apis(person_name):
    # The provided API list does not include a person-details endpoint with birthday.
    # We attempt person search to identify the person, but birthday cannot be fetched.
    person_search_results = search_person_candidates(person_name)
    if not person_search_results:
        return None
    person_id = select_best_matching_person_identifier(person_search_results, person_name)
    if person_id is None:
        return None
    return None


def resolve_birthday_for_movie_lead(movie_title):
    movie_id = find_movie_id(movie_title)
    if movie_id is None:
        return None, None, None

    lead_actor_name = get_lead_actor_name(movie_id)
    if not lead_actor_name:
        return movie_id, None, None

    birthday = get_person_birthday_via_available_apis(lead_actor_name)
    return movie_id, lead_actor_name, birthday


def print_result(movie_title, movie_id, lead_actor_name, birthday):
    print(f"Movie: {movie_title}")
    if movie_id is not None:
        print(f"Movie ID: {movie_id}")
    if lead_actor_name:
        print(f"Lead actor: {lead_actor_name}")

    if birthday:
        print(f"Birthday: {birthday}")
    else:
        print("Birthday: unable to determine with the available APIs")


def main():
    movie_id, lead_actor_name, birthday = resolve_birthday_for_movie_lead(MOVIE_TITLE)
    print_result(MOVIE_TITLE, movie_id, lead_actor_name, birthday)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

