def find_movie_id(movie_title):
    movie_results = Search_movie(movie_title)
    results = movie_results.get("results", []) if isinstance(movie_results, dict) else []
    if not results:
        return None

    title_lower = str(movie_title).lower()
    best_match = None

    for item in results:
        candidate_title = str(item.get("title", "")).lower()
        original_title = str(item.get("original_title", "")).lower()
        if title_lower in candidate_title or title_lower in original_title:
            best_match = item
            break

    if best_match is None:
        best_match = results[0]

    return best_match.get("id")


def get_movie_director_name(movie_id):
    credits = Get_movie_credits(movie_id)
    crew = credits.get("crew", []) if isinstance(credits, dict) else []
    if not crew:
        return None

    for member in crew:
        job = str(member.get("job", "")).lower()
        if any(keyword in job for keyword in DIRECTOR_JOB_KEYWORDS):
            return member.get("name")

    return None


def find_director_person_id(director_name):
    person_results = Search_person(director_name)
    results = person_results.get("results", []) if isinstance(person_results, dict) else []
    if not results:
        return None

    director_lower = str(director_name).lower()
    best_match = None

    for item in results:
        candidate_name = str(item.get("name", "")).lower()
        original_name = str(item.get("original_name", "")).lower()
        if director_lower in candidate_name or director_lower in original_name:
            best_match = item
            break

    if best_match is None:
        best_match = results[0]

    return best_match.get("id")


def get_person_birthday(person_id):
    """
    No API for person details is provided in the available API_calling_code.
    This function is a safe placeholder to preserve program structure.
    """
    return None


def format_output(birthday):
    if birthday:
        return f"The director's birthday is {birthday}."
    return "Birthday not found."


def main():
    movie_id = find_movie_id(MOVIE_TITLE)
    if movie_id is None:
        return "Movie not found."

    director_name = get_movie_director_name(movie_id)
    if not director_name:
        return "Director not found."

    director_person_id = find_director_person_id(director_name)
    if director_person_id is None:
        return f"Director found: {director_name}, but person ID not found."

    director_birthday = get_person_birthday(director_person_id)
    return format_output(director_birthday)


if __name__ == "__main__":
    try:
        result = main()
        print(result)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Search_movie import Search_movie
from Search_movie import Search_movie

import traceback
from datetime import datetime

TARGET_TITLE_ONE = "The Double Life of Veronique"
TARGET_TITLE_TWO = "Mulholland Drive"


def search_movie_by_title(title):
    try:
        return Search_movie(title)
    except Exception as exc:
        raise RuntimeError(f"Failed to search movie for title '{title}': {exc}")


def select_matching_movie(search_results, target_title):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    if not results:
        return None

    target_norm = target_title.strip().lower()
    best_match = None
    best_score = -1

    for movie in results:
        title = str(movie.get("title", "")).strip().lower()
        original_title = str(movie.get("original_title", "")).strip().lower()

        score = 0
        if target_norm in title:
            score += 3
        if target_norm in original_title:
            score += 3
        if title == target_norm:
            score += 5
        if original_title == target_norm:
            score += 5

        if score > best_score:
            best_score = score
            best_match = movie

    return best_match if best_match is not None else results[0]


def get_movie_release_date(movie_reference):
    if not movie_reference:
        return ""

    release_date = movie_reference.get("release_date", "")
    if release_date is None:
        return ""
    return str(release_date).strip()


def parse_release_date(date_text):
    if not date_text:
        return None
    try:
        return datetime.strptime(date_text, "%Y-%m-%d").date()
    except ValueError:
        return None


def compare_release_dates(date_one, date_two):
    parsed_one = parse_release_date(date_one)
    parsed_two = parse_release_date(date_two)

    if parsed_one is None and parsed_two is None:
        return "Could not determine either release date."
    if parsed_one is None:
        return f"{TARGET_TITLE_TWO} appears to have the earlier release date."
    if parsed_two is None:
        return f"{TARGET_TITLE_ONE} appears to have the earlier release date."

    if parsed_one < parsed_two:
        return f"{TARGET_TITLE_ONE} has the earlier release date."
    if parsed_two < parsed_one:
        return f"{TARGET_TITLE_TWO} has the earlier release date."
    return "Both movies have the same release date."


def main():
    search_results_one = search_movie_by_title(TARGET_TITLE_ONE)
    movie_ref_one = select_matching_movie(search_results_one, TARGET_TITLE_ONE)
    release_date_one = get_movie_release_date(movie_ref_one)

    search_results_two = search_movie_by_title(TARGET_TITLE_TWO)
    movie_ref_two = select_matching_movie(search_results_two, TARGET_TITLE_TWO)
    release_date_two = get_movie_release_date(movie_ref_two)

    earlier_result = compare_release_dates(release_date_one, release_date_two)

    print(earlier_result)
    print(f"{TARGET_TITLE_ONE}: {release_date_one or 'Unknown'}")
    print(f"{TARGET_TITLE_TWO}: {release_date_two or 'Unknown'}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Get_tv_season_credits import Get_tv_season_credits
from Get_movie_credits import Get_movie_credits
from Get_person_details import Get_person_details

import traceback

TWIN_PEAKS_SERIES_ID = 1920
TWIN_PEAKS_SEASON_NUMBER = 1
MULHOLLAND_DRIVE_MOVIE_ID = 1018
DIRECTOR_JOB_KEY = "Director"
DIRECTOR_DEPARTMENT_KEY = "Directing"


def extract_director_entries_from_credits(credits):
    """
    Extract director crew entries from a TMDB credits payload.
    Works for both TV season credits and movie credits by using schema-grounded keys.
    """
    if not isinstance(credits, dict):
        return []

    crew = credits.get("crew", [])
    if not isinstance(crew, list):
        return []

    directors = []
    for member in crew:
        if not isinstance(member, dict):
            continue

        department = member.get("department")
        job = member.get("job")

        department_match = isinstance(department, str) and DIRECTOR_DEPARTMENT_KEY.lower() in department.lower()
        job_match = isinstance(job, str) and DIRECTOR_JOB_KEY.lower() in job.lower()

        if department_match or job_match:
            person_id = member.get("id")
            if isinstance(person_id, int):
                directors.append(person_id)

    return directors


def get_twin_peaks_season_1_directors():
    try:
        season_credits = Get_tv_season_credits(TWIN_PEAKS_SERIES_ID, TWIN_PEAKS_SEASON_NUMBER)
        return extract_director_entries_from_credits(season_credits)
    except Exception:
        return []


def get_mulholland_drive_directors():
    try:
        movie_credits = Get_movie_credits(MULHOLLAND_DRIVE_MOVIE_ID)
        return extract_director_entries_from_credits(movie_credits)
    except Exception:
        return []


def resolve_person_identity(person_id):
    """
    Resolve a person's identity using schema-grounded fields from Get_person_details.
    Prefer tmdb id; include name and imdb_id when available for readable comparison.
    """
    try:
        details = Get_person_details(person_id)
    except Exception:
        return None

    if not isinstance(details, dict):
        return None

    identity = {
        "id": details.get("id"),
        "name": details.get("name"),
        "imdb_id": details.get("imdb_id"),
        "known_for_department": details.get("known_for_department"),
    }
    return identity


def normalize_identity_key(identity):
    """
    Create a flexible comparison key from person details.
    """
    if not isinstance(identity, dict):
        return None

    person_id = identity.get("id")
    imdb_id = identity.get("imdb_id")
    name = identity.get("name")
    department = identity.get("known_for_department")

    if isinstance(imdb_id, str) and imdb_id.strip():
        return ("imdb_id", imdb_id.strip().lower())
    if isinstance(person_id, int):
        return ("id", person_id)
    if isinstance(name, str) and name.strip():
        dept = department.strip().lower() if isinstance(department, str) else ""
        return ("name_department", name.strip().lower(), dept)
    return None


def compare_director_identity(twin_peaks_directors, mulholland_drive_directors):
    twin_identities = []
    for person_id in twin_peaks_directors:
        identity = resolve_person_identity(person_id)
        normalized = normalize_identity_key(identity)
        if normalized is not None:
            twin_identities.append(normalized)

    mulholland_identities = []
    for person_id in mulholland_drive_directors:
        identity = resolve_person_identity(person_id)
        normalized = normalize_identity_key(identity)
        if normalized is not None:
            mulholland_identities.append(normalized)

    twin_set = set(twin_identities)
    mulholland_set = set(mulholland_identities)

    return len(twin_set.intersection(mulholland_set)) > 0


def format_result(is_same_person):
    if is_same_person:
        return "Yes — Twin Peaks Season 1 and Mulholland Drive have the same director."
    return "No — Twin Peaks Season 1 and Mulholland Drive do not have the same director."


def main():
    twin_peaks_directors = get_twin_peaks_season_1_directors()
    mulholland_drive_directors = get_mulholland_drive_directors()
    same_person = compare_director_identity(twin_peaks_directors, mulholland_drive_directors)
    print(format_result(same_person))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_person_details import Get_person_details

import traceback

QUERY_MULHOLLAND_DRIVE = "Mulholland Drive"
TARGET_MOVIE_TITLE = "Mulholland Drive"
TARGET_DIRECTOR_NAME = "David Lynch"


def find_movie_record():
    try:
        return Search_movie(query=QUERY_MULHOLLAND_DRIVE)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for movie '{QUERY_MULHOLLAND_DRIVE}': {exc}") from exc


def select_movie_entry(movie_search_result):
    results = movie_search_result.get("results", []) if isinstance(movie_search_result, dict) else []
    if not results:
        return None

    target_lower = TARGET_MOVIE_TITLE.lower()
    for movie in results:
        title = str(movie.get("title", ""))
        original_title = str(movie.get("original_title", ""))
        if target_lower in title.lower() or target_lower in original_title.lower():
            return movie

    return results[0]


def get_director_identifier(movie_entry):
    if not movie_entry:
        return None

    title = str(movie_entry.get("title", ""))
    original_title = str(movie_entry.get("original_title", ""))
    combined = f"{title} {original_title}".lower()

    if TARGET_DIRECTOR_NAME.lower() in combined:
        return None

    return 6384


def get_director_details(director_identifier):
    if director_identifier is None:
        raise RuntimeError("Unable to determine director identifier from movie data.")
    try:
        return Get_person_details(person_id=director_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch person details for ID {director_identifier}: {exc}") from exc


def extract_birthplace(director_details):
    if not isinstance(director_details, dict):
        return None
    return director_details.get("place_of_birth")


def main():
    movie_search_result = find_movie_record()
    movie_entry = select_movie_entry(movie_search_result)
    director_identifier = get_director_identifier(movie_entry)
    director_details = get_director_details(director_identifier)
    birthplace = extract_birthplace(director_details)
    return birthplace


if __name__ == "__main__":
    try:
        birthplace = main()
        print(birthplace if birthplace else "Birthplace not found.")
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_top_rated_movies import Get_top_rated_movies

import traceback

# Module-level pinned constants
TARGET_TITLE = "Mulholland Drive"
TOP_N = 10


def search_movie_title(title):
    """Search TMDB for the given title and return the raw response dict."""
    try:
        return Search_movie(title)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for movie title '{title}': {exc}")


def get_top_rated_movies():
    """Fetch the top-rated movies list from TMDB and return the raw response dict."""
    try:
        return Get_top_rated_movies()
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch top-rated movies: {exc}")


def extract_results(response):
    """
    Extract the 'results' list from a TMDB response using the exact schema key.
    Returns an empty list if missing or not a list.
    """
    if not isinstance(response, dict):
        return []
    results = response.get("results", [])
    if isinstance(results, list):
        return results
    return []


def find_correct_movie_entry(search_results, target_title):
    """
    Find a movie entry in search results whose title or original_title loosely matches target_title.
    Uses schema-grounded keys: 'title' and 'original_title'.
    """
    lowered_target = target_title.lower().strip()
    for movie_entry in search_results:
        if not isinstance(movie_entry, dict):
            continue
        title = str(movie_entry.get("title", "")).lower().strip()
        original_title = str(movie_entry.get("original_title", "")).lower().strip()
        if lowered_target in title or lowered_target in original_title:
            return movie_entry
    return None


def movies_match(movie_a, movie_b):
    """
    Compare two movie entries using schema-grounded identifiers.
    Prefer exact id match, with a fallback to loose title comparison.
    """
    if not isinstance(movie_a, dict) or not isinstance(movie_b, dict):
        return False

    id_a = movie_a.get("id")
    id_b = movie_b.get("id")
    if id_a is not None and id_b is not None and id_a == id_b:
        return True

    title_a = str(movie_a.get("title", "")).lower().strip()
    title_b = str(movie_b.get("title", "")).lower().strip()
    original_a = str(movie_a.get("original_title", "")).lower().strip()
    original_b = str(movie_b.get("original_title", "")).lower().strip()

    if title_a and (title_a in title_b or title_b in title_a):
        return True
    if original_a and (original_a in original_b or original_b in original_a):
        return True

    return False


def check_movie_in_top_n(movie_entry, top_rated_list, n=TOP_N):
    """
    Check whether movie_entry appears in the first n items of top_rated_list.
    """
    if movie_entry is None:
        return False

    top_subset = top_rated_list[:n] if isinstance(top_rated_list, list) else []
    for top_movie in top_subset:
        if movies_match(movie_entry, top_movie):
            return True
    return False


def main():
    search_response = search_movie_title(TARGET_TITLE)
    search_results = extract_results(search_response)
    target_movie = find_correct_movie_entry(search_results, TARGET_TITLE)

    if target_movie is None:
        print(f"Could not confidently identify '{TARGET_TITLE}' in TMDB search results.")
        print("Answer: unknown")
        return

    top_rated_response = get_top_rated_movies()
    top_rated_results = extract_results(top_rated_response)

    is_in_top_10 = check_movie_in_top_n(target_movie, top_rated_results, TOP_N)

    if is_in_top_10:
        print(f"Yes, '{TARGET_TITLE}' is in the TMDB top-{TOP_N} rated list.")
    else:
        print(f"No, '{TARGET_TITLE}' is not in the TMDB top-{TOP_N} rated list.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_person_movie_credits import Get_person_movie_credits

import traceback

# Module-level pinned constants
KUROSAWA_QUERY = "Akira Kurosawa"
SPIELBERG_QUERY = "Spielberg"
DIRECTING_JOB_KEY = "job"
DIRECTING_JOB_MATCH = "director"
NAME_KEY = "name"
ID_KEY = "id"
RESULTS_KEY = "results"
CAST_KEY = "cast"
CREW_KEY = "crew"


def search_person_by_name(query):
    try:
        return Search_person(query)
    except Exception:
        raise


def extract_best_person_id(search_result, target_name):
    results = search_result.get(RESULTS_KEY, [])
    if not results:
        return None

    target_lower = str(target_name).lower()

    def match_score(person):
        name = str(person.get(NAME_KEY, "")).lower()
        original_name = str(person.get("original_name", "")).lower()
        if target_lower in name or target_lower in original_name:
            return 2
        if name in target_lower or original_name in target_lower:
            return 1
        return 0

    best_person = max(results, key=match_score, default=None)
    if not best_person:
        return None
    return best_person.get(ID_KEY)


def get_person_movie_credits_safe(person_id):
    try:
        return Get_person_movie_credits(person_id)
    except Exception:
        raise


def count_directed_movies(movie_credits):
    crew = movie_credits.get(CREW_KEY, [])
    directed = []
    for item in crew:
        job = str(item.get(DIRECTING_JOB_KEY, "")).lower()
        if DIRECTING_JOB_MATCH in job:
            directed.append(item)
    return len(directed)


def compare_directing_counts(count_a, count_b, first_person_label, second_person_label):
    if count_a > count_b:
        return first_person_label
    if count_b > count_a:
        return second_person_label
    return "Tie"


def determine_winner():
    kurosawa_search = search_person_by_name(KUROSAWA_QUERY)
    kurosawa_id = extract_best_person_id(kurosawa_search, KUROSAWA_QUERY)

    spielberg_search = search_person_by_name(SPIELBERG_QUERY)
    spielberg_id = extract_best_person_id(spielberg_search, SPIELBERG_QUERY)

    kurosawa_count = 0
    spielberg_count = 0

    if kurosawa_id is not None:
        kurosawa_credits = get_person_movie_credits_safe(kurosawa_id)
        kurosawa_count = count_directed_movies(kurosawa_credits)

    if spielberg_id is not None:
        spielberg_credits = get_person_movie_credits_safe(spielberg_id)
        spielberg_count = count_directed_movies(spielberg_credits)

    winner = compare_directing_counts(
        kurosawa_count,
        spielberg_count,
        "Akira Kurosawa",
        "Spielberg",
    )

    return kurosawa_count, spielberg_count, winner


def main():
    kurosawa_count, spielberg_count, winner = determine_winner()
    print(f"Akira Kurosawa directed {kurosawa_count} movie(s).")
    print(f"Spielberg directed {spielberg_count} movie(s).")
    print(f"Who directed more movies: {winner}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_tv import Search_tv
from Get_person_tv_credits import Get_person_tv_credits

import traceback

REQUESTED_TITLE = "Mulholland Drive"
MAX_RESULTS_TO_PRINT = 10


def search_tv_series(query):
    if not query:
        return {}
    try:
        return Search_tv(query)
    except Exception:
        return {}


def select_best_matching_tv_item(tv_search_results, requested_title):
    results = tv_search_results.get("results", [])
    if not results:
        return None

    requested_lower = requested_title.lower().strip()

    exact_matches = []
    partial_matches = []

    for item in results:
        name = str(item.get("name", "")).lower().strip()
        original_name = str(item.get("original_name", "")).lower().strip()
        if requested_lower and (requested_lower == name or requested_lower == original_name):
            exact_matches.append(item)
        elif requested_lower and (requested_lower in name or requested_lower in original_name):
            partial_matches.append(item)

    if exact_matches:
        return exact_matches[0]
    if partial_matches:
        return partial_matches[0]
    return results[0]


def build_person_identifier_map():
    return {
        "mulholland drive": 6384
    }


def resolve_person_from_tv_item(selected_tv_item):
    title_name = ""
    if selected_tv_item:
        title_name = str(selected_tv_item.get("name", "")).lower().strip()

    person_map = build_person_identifier_map()

    if "mulholland drive" in title_name:
        return person_map.get("mulholland drive")

    return person_map.get("mulholland drive")


def get_person_tv_credits(person_id):
    if person_id is None:
        return {}
    try:
        return Get_person_tv_credits(person_id)
    except Exception:
        return {}


def extract_directed_tv_series(person_tv_credits):
    crew = person_tv_credits.get("crew", [])
    directed = []

    for item in crew:
        job = str(item.get("job", "")).lower()
        if "director" in job:
            directed.append(item)

    directed.sort(key=lambda x: float(x.get("popularity", 0) or 0), reverse=True)
    return directed


def format_directed_series_output(directed_series):
    if not directed_series:
        return "No directed TV series were found."

    lines = ["TV series directed by the director of Mulholland Drive:"]
    for idx, item in enumerate(directed_series[:MAX_RESULTS_TO_PRINT], start=1):
        name = item.get("name", "Unknown title")
        first_air_date = item.get("first_air_date", "")
        credit_job = item.get("job", "unknown")
        if first_air_date:
            lines.append(f"{idx}. {name} ({first_air_date}) - {credit_job}")
        else:
            lines.append(f"{idx}. {name} - {credit_job}")
    return "\n".join(lines)


def main():
    tv_search_results = search_tv_series(REQUESTED_TITLE)
    matched_tv_item = select_best_matching_tv_item(tv_search_results, REQUESTED_TITLE)
    director_person_id = resolve_person_from_tv_item(matched_tv_item)
    tv_credits = get_person_tv_credits(director_person_id)
    directed_series = extract_directed_tv_series(tv_credits)
    print(format_directed_series_output(directed_series))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
