from Search_tv import Search_tv
from Get_tv_details import Get_tv_details

import traceback

QUERY_SWORD_ART_ONLINE = "Sword Art Online"


def search_show_title(query):
    """
    Search for a TV show and return the raw API result.
    """
    try:
        return Search_tv(query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV show for query={query!r}") from exc


def get_show_details(series_id):
    """
    Get detailed show information for a TV series ID.
    """
    try:
        return Get_tv_details(series_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to get TV details for series_id={series_id!r}") from exc


def extract_first_series_id(search_result):
    """
    Extract the first matching series ID from the Search_tv response schema.
    Expected path: results[0].id
    """
    results = search_result.get("results", [])
    if not results:
        return None
    first_item = results[0]
    return first_item.get("id")


def extract_season_count(show_details):
    """
    Extract the season count from the Get_tv_details response schema.
    Expected key: number_of_seasons
    """
    return show_details.get("number_of_seasons")


def main():
    search_result = search_show_title(QUERY_SWORD_ART_ONLINE)
    series_id = extract_first_series_id(search_result)

    if series_id is None:
        print("No TV show results found for Sword Art Online.")
        return

    show_details = get_show_details(series_id)
    total_seasons = extract_season_count(show_details)

    if total_seasons is None:
        print("Could not determine the number of seasons for Sword Art Online.")
        return

    print(f"Sword Art Online has {total_seasons} seasons.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

