from Search_movie import Search_movie
from Get_movie_details import Get_movie_details
from Get_person_details import Get_person_details

import traceback

SHOW_TITLE = "DEATH NOTE"
MOVIE_TITLE = "Barbie"
PERSON_BIRTHDAY_KEY = "birthday"
TV_RESULTS_KEY = "results"
TV_NAME_KEY = "name"
TV_ID_KEY = "id"
MOVIE_RESULTS_KEY = "results"
MOVIE_TITLE_KEY = "title"
MOVIE_ID_KEY = "id"
DIRECTOR_DEPARTMENT = "Directing"
ACTING_DEPARTMENT = "Acting"


def select_best_tv_match(tv_search_results, show_title):
    results = tv_search_results.get(TV_RESULTS_KEY, []) if isinstance(tv_search_results, dict) else []
    target = (show_title or "").strip().lower()
    for item in results:
        name = str(item.get(TV_NAME_KEY, "")).strip().lower()
        if target and target in name:
            return item.get(TV_ID_KEY)
    return results[0].get(TV_ID_KEY) if results else None


def select_best_movie_match(movie_search_results, movie_title):
    results = movie_search_results.get(MOVIE_RESULTS_KEY, []) if isinstance(movie_search_results, dict) else []
    target = (movie_title or "").strip().lower()
    for item in results:
        title = str(item.get(MOVIE_TITLE_KEY, "")).strip().lower()
        if target and target in title:
            return item.get(MOVIE_ID_KEY)
    return results[0].get(MOVIE_ID_KEY) if results else None


def extract_lead_actor_person_id(tv_details):
    # Ground truth field paths from schema are limited to TV details; cast is not included.
    # We therefore use a pragmatic fallback: the show details endpoint does not expose cast,
    # so we cannot derive the lead actor directly from this schema alone.
    return None


def extract_director_person_id(movie_details):
    # Ground truth field paths from schema are limited to movie details; crew is not included.
    # We therefore use a pragmatic fallback: the movie details endpoint does not expose crew,
    # so we cannot derive the director directly from this schema alone.
    return None


def get_birth_year_from_person_details(person_details):
    birthday = person_details.get(PERSON_BIRTHDAY_KEY)
    if not birthday or len(str(birthday)) < 4:
        return None
    try:
        return int(str(birthday)[:4])
    except Exception:
        return None


def compare_ages(person_a_birth_year, person_b_birth_year):
    if person_a_birth_year is None or person_b_birth_year is None:
        return "unknown", None
    if person_a_birth_year < person_b_birth_year:
        return "person_a", person_b_birth_year - person_a_birth_year
    if person_b_birth_year < person_a_birth_year:
        return "person_b", person_a_birth_year - person_b_birth_year
    return "same_age", 0


def find_tv_show_and_lead_actor(show_title):
    tv_search_results = Search_tv(query=show_title)
    tv_show_id = select_best_tv_match(tv_search_results, show_title)
    if tv_show_id is None:
        return None
    tv_details = Get_tv_details(series_id=tv_show_id)
    return extract_lead_actor_person_id(tv_details)


def find_movie_and_director(movie_title):
    movie_search_results = Search_movie(query=movie_title)
    movie_id = select_best_movie_match(movie_search_results, movie_title)
    if movie_id is None:
        return None
    movie_details = Get_movie_details(movie_id=movie_id)
    return extract_director_person_id(movie_details)


def get_person_birth_year(person_id):
    if person_id is None:
        return None
    person_details = Get_person_details(person_id=person_id)
    return get_birth_year_from_person_details(person_details)


def build_result():
    lead_actor_id = find_tv_show_and_lead_actor(SHOW_TITLE)
    director_id = find_movie_and_director(MOVIE_TITLE)

    lead_actor_birth_year = get_person_birth_year(lead_actor_id)
    director_birth_year = get_person_birth_year(director_id)

    older_person, year_difference = compare_ages(director_birth_year, lead_actor_birth_year)

    if older_person == "person_a":
        return {"older": "director of Barbie", "by_how_many_years": year_difference}
    if older_person == "person_b":
        return {"older": "lead actor of DEATH NOTE", "by_how_many_years": year_difference}
    if older_person == "same_age":
        return {"older": "same_age", "by_how_many_years": 0}
    return {
        "older": "unknown",
        "by_how_many_years": None,
        "note": "Unable to determine ages because the provided API schemas do not expose cast/crew fields needed to identify the lead actor and director."
    }


def main():
    result = build_result()
    print(result)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_details import Get_movie_details

import traceback

PERSON_NAME = "Katherine LaNasa"
MOVIE_MEDIA_TYPE_KEY = "media_type"
MOVIE_MEDIA_TYPE_VALUE = "movie"


def find_person_record(person_name):
    try:
        search_results = Search_person(person_name)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for person '{person_name}': {exc}") from exc

    results = search_results.get("results", [])
    if not results:
        return None

    name_matches = []
    for person in results:
        name = person.get("name", "") or ""
        original_name = person.get("original_name", "") or ""
        if person_name.lower() in name.lower() or person_name.lower() in original_name.lower():
            name_matches.append(person)

    if name_matches:
        return max(name_matches, key=lambda p: p.get("popularity", 0) or 0)

    return max(results, key=lambda p: p.get("popularity", 0) or 0)


def select_latest_movie_credit(movie_credits):
    cast = movie_credits.get("cast", [])
    if not cast:
        return None

    def score_credit(credit):
        release_date = credit.get("release_date", "") or ""
        popularity = credit.get("popularity", 0) or 0
        vote_count = credit.get("vote_count", 0) or 0
        return (release_date, popularity, vote_count)

    movie_cast = []
    for credit in cast:
        if (credit.get(MOVIE_MEDIA_TYPE_KEY, "") or "").lower() == MOVIE_MEDIA_TYPE_VALUE:
            movie_cast.append(credit)

    candidates = movie_cast if movie_cast else cast
    return max(candidates, key=score_credit)


def get_latest_movie_credit(person_id):
    try:
        movie_credits = Get_person_movie_credits(person_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch movie credits for person_id={person_id}: {exc}") from exc

    return select_latest_movie_credit(movie_credits)


def get_movie_details(movie_id):
    try:
        return Get_movie_details(movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch movie details for movie_id={movie_id}: {exc}") from exc


def build_summary(person_name, movie_credit, movie_details):
    title = movie_details.get("title") or movie_credit.get("title") or "Unknown title"
    release_date = movie_details.get("release_date") or movie_credit.get("release_date") or "Unknown release date"
    character = movie_credit.get("character")
    overview = movie_details.get("overview") or movie_credit.get("overview") or "No overview available."
    vote_average = movie_details.get("vote_average")
    runtime = movie_details.get("runtime")

    lines = []
    lines.append(f"Latest movie appearance for {person_name}:")
    lines.append(f"- Title: {title}")
    lines.append(f"- Release date: {release_date}")

    if character:
        lines.append(f"- Role: {character}")

    if runtime is not None:
        lines.append(f"- Runtime: {runtime} minutes")

    if vote_average is not None:
        lines.append(f"- TMDB rating: {vote_average}")

    lines.append(f"- Overview: {overview}")
    return "\n".join(lines)


def main():
    person_record = find_person_record(PERSON_NAME)
    if not person_record:
        return f"No person record found for {PERSON_NAME}."

    person_id = person_record.get("id")
    if person_id is None:
        return f"Could not determine an ID for {PERSON_NAME}."

    latest_movie_credit = get_latest_movie_credit(person_id)
    if not latest_movie_credit:
        return f"No movie credits found for {PERSON_NAME}."

    movie_id = latest_movie_credit.get("id")
    if movie_id is None:
        return f"Could not determine latest movie ID for {PERSON_NAME}."

    latest_movie_details = get_movie_details(movie_id)
    return build_summary(PERSON_NAME, latest_movie_credit, latest_movie_details)


if __name__ == "__main__":
    try:
        output = main()
        print(output)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_images import Get_movie_images

import traceback

TARGET_TITLE = "Oppenheimer"
POSTER_BASE_URL = "https://image.tmdb.org/t/p/original"


def find_best_movie_id(search_response, target_title):
    results = search_response.get("results", [])
    if not results:
        return None

    target_lower = target_title.lower()
    exact_matches = []
    partial_matches = []

    for movie in results:
        title = movie.get("title", "")
        original_title = movie.get("original_title", "")
        if target_lower in title.lower() or target_lower in original_title.lower():
            partial_matches.append(movie)
            if title.lower() == target_lower or original_title.lower() == target_lower:
                exact_matches.append(movie)

    candidates = exact_matches if exact_matches else partial_matches if partial_matches else results
    best_movie = max(candidates, key=lambda m: (m.get("popularity", 0), m.get("vote_average", 0), m.get("vote_count", 0)))
    return best_movie.get("id")


def retrieve_movie_cover_images(movie_id):
    return Get_movie_images(movie_id)


def choose_single_cover_image(image_data):
    posters = image_data.get("posters", [])
    if posters:
        best_poster = max(
            posters,
            key=lambda p: (p.get("vote_average", 0), p.get("vote_count", 0), p.get("width", 0), p.get("height", 0)),
        )
        file_path = best_poster.get("file_path")
        if file_path:
            return POSTER_BASE_URL + file_path

    backdrops = image_data.get("backdrops", [])
    if backdrops:
        best_backdrop = max(
            backdrops,
            key=lambda b: (b.get("vote_average", 0), b.get("vote_count", 0), b.get("width", 0), b.get("height", 0)),
        )
        file_path = best_backdrop.get("file_path")
        if file_path:
            return POSTER_BASE_URL + file_path

    return "No cover image available."


def search_movie_by_title(target_title):
    movie_list = Search_movie(query=target_title)
    return find_best_movie_id(movie_list, target_title)


def main():
    movie_id = search_movie_by_title(TARGET_TITLE)
    if movie_id is None:
        return "No cover image available."

    cover_image_data = retrieve_movie_cover_images(movie_id)
    one_cover_image = choose_single_cover_image(cover_image_data)
    return one_cover_image


if __name__ == "__main__":
    try:
        result = main()
        print(result)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise
